import { constants, type Dirent } from "node:fs";
import path from "node:path";
import type { FileHandle } from "node:fs/promises";
import { TextDecoder } from "node:util";
import { createPackagePathsModule } from "./package-paths.js";
import type { FilesystemPort } from "./ports.js";

const TEXT_EXTENSIONS: ReadonlySet<string> = new Set([".md", ".mdx", ".txt", ".json", ".yaml", ".yml", ".ts", ".tsx", ".js", ".jsx", ".css", ".html", ".csv", ".svg", ".py", ".sh"]);
const MAX_FILE_BYTES = 256 * 1024;
const MAX_WALK_ENTRIES = 4096;
const MAX_WALK_DEPTH = 32;
const TOO_LARGE = "File request refused: exceeds the 256 KiB text limit; no content returned.";

const UNREADABLE = "File request refused: file is missing or unreadable.";

/** A read either yields text or the one refusal message the model may see. */
type ReadOutcome = { readonly text: string } | { readonly refusal: string };

/** Reads an opened regular file of at most the cap; a file that grows past it after `stat` is still refused. */
async function readOpened(handle: FileHandle): Promise<ReadOutcome> {
  const stat = await handle.stat();
  if (!stat.isFile()) return { refusal: "File request refused: only regular text files are readable." };
  if (stat.size > MAX_FILE_BYTES) return { refusal: TOO_LARGE };
  const buffer = Buffer.alloc(MAX_FILE_BYTES + 1);
  let length = 0;
  while (length < buffer.length) {
    const { bytesRead } = await handle.read(buffer, length, buffer.length - length, null);
    if (!bytesRead) break;
    length += bytesRead;
  }
  return length > MAX_FILE_BYTES ? { refusal: TOO_LARGE } : decodeText(buffer.subarray(0, length));
}

/** Admit only control-free UTF-8 text (tab, LF and CR allowed). */
function decodeText(bytes: Buffer): ReadOutcome {
  if (bytes.some(byte => (byte < 32 && byte !== 9 && byte !== 10 && byte !== 13) || byte === 127)) return { refusal: "File request refused: binary content cannot be read as text." };
  try { return { text: new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes) }; }
  catch { return { refusal: "File request refused: binary or invalid UTF-8 content cannot be read as text." }; }
}

/** Model-visible result. Paths are relative to ONE skill; filesystem errors never cross this seam. */
export interface SkillFileResult {
  readonly text: string;
  readonly files: readonly string[];
  readonly note?: string;
}
export interface SkillFileReader {
  read(input: Record<string, never>, options?: { readonly file?: string }): Promise<SkillFileResult>;
}

/**
 * Progressive disclosure for plugin AND standalone skills, with a skill-folder trust boundary.
 * Uses the lifecycle containment owner, native bounded reads and injected async filesystem effects.
 * The default file is SKILL.md; supporting files are discovered recursively, never inlined.
 * @complexity O(entries + readable bytes), bounded by 4096 entries, depth 32 and 256 KiB per file.
 */
export function createSkillFileReader(
  { skillRoot, filesystem }: { readonly skillRoot: string; readonly filesystem: FilesystemPort },
  _options: Record<string, never> = {},
): SkillFileReader {
  const { assertContainedOnDisk } = createPackagePathsModule({ filesystem });

  /** Reject traversal even when normalization would leave it inside the folder.
   * @returns The refusal message, or `undefined` for an admissible name. */
  function validateFile(file: string): string | undefined {
    if (!file || file.includes("\0") || file.includes("\\") || path.posix.isAbsolute(file) || /^[a-zA-Z]:/.test(file) || file.split("/").some(segment => segment === "..")) {
      return "File request refused: use a path relative to this skill folder, without traversal or absolute paths.";
    }
    if (!TEXT_EXTENSIONS.has(path.extname(file).toLowerCase())) {
      return "File request refused: only supported text extensions are readable.";
    }
    return undefined;
  }

  /** The canonical contained target of `file`, or `undefined` when it is missing or escapes the folder. */
  async function resolveTarget(file: string): Promise<string | undefined> {
    try {
      const absolute = await filesystem.realpath(await assertContainedOnDisk(skillRoot, file));
      // Recheck the canonical target through the same owner before opening it.
      const relative = path.relative(await filesystem.realpath(skillRoot), absolute);
      await assertContainedOnDisk(skillRoot, relative);
      return validateFile(relative.split(path.sep).join("/")) === undefined ? absolute : undefined;
    } catch {
      return undefined;
    }
  }

  /** Validate, resolve, then read one file; every refusal is a value, never a thrown native error. */
  async function readText(file: string): Promise<ReadOutcome> {
    const invalid = validateFile(file);
    if (invalid !== undefined) return { refusal: invalid };
    const absolute = await resolveTarget(file);
    if (absolute === undefined) return { refusal: "File request refused: file is missing, unreadable, or resolves outside this skill folder." };
    return readContained(absolute);
  }

  /** Open the resolved target with no-follow and read at most cap + 1, including growing files. */
  async function readContained(absolute: string): Promise<ReadOutcome> {
    const handle = await filesystem.open(absolute, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK).catch(() => undefined);
    if (!handle) return { refusal: UNREADABLE };
    // Never reflect native errors or caller paths: either can contain an absolute host path.
    return readOpened(handle).catch(() => ({ refusal: UNREADABLE })).finally(() => handle.close().catch(() => {}));
  }

  /** Skip directory symlinks (including cycles); contained file symlinks use the same read guard. */
  async function listFiles(): Promise<{ files: string[]; note?: string }> {
    const files: string[] = [];
    let remaining = MAX_WALK_ENTRIES;
    let incomplete = false;
    async function walk(relative: string, depth: number): Promise<void> {
      if (depth > MAX_WALK_DEPTH || remaining <= 0) { incomplete = true; return; }
      const entries = await readDirectory(relative);
      if (!entries) { incomplete = true; return; }
      for (const entry of entries) {
        if (remaining-- <= 0) { incomplete = true; break; }
        await visit(entry, relative ? `${relative}/${entry.name}` : entry.name, depth);
      }
    }
    async function visit(entry: Dirent, file: string, depth: number): Promise<void> {
      if (entry.isDirectory()) return walk(file, depth + 1);
      if (file === "SKILL.md" || !(entry.isFile() || entry.isSymbolicLink())) return;
      // Refused files must not be advertised as readable.
      if ("text" in await readText(file)) files.push(file);
    }
    await walk("", 0);
    return { files: files.sort(), ...(incomplete ? { note: "Supporting-file inventory is incomplete: traversal limit reached or a directory is unreadable." } : {}) };
  }

  /** One directory's entries in code-unit name order, or `undefined` when it cannot be read. */
  async function readDirectory(relative: string): Promise<Dirent[] | undefined> {
    try {
      const directory = relative ? await assertContainedOnDisk(skillRoot, relative) : await filesystem.realpath(skillRoot);
      return (await filesystem.readdir(directory, { withFileTypes: true })).sort((a, b) => Number(a.name > b.name) - Number(a.name < b.name));
    } catch { return undefined; }
  }

  return {
    async read(_input, options = {}) {
      const listing = await listFiles();
      const outcome = await readText(options.file ?? "SKILL.md");
      if ("text" in outcome) return { ...listing, text: outcome.text };
      return { files: listing.files, text: "", note: [outcome.refusal, `Valid supporting files: ${listing.files.join(", ") || "(none)"}. Omit file to request SKILL.md.`, listing.note].filter(Boolean).join(" ") };
    },
  };
}

mutants.replacement:
artifacts !== undefined || {
  artifacts: Object.freeze({
    write: guard((input: ArtifactWriteInput) => artifacts.write(input))
  })
}

src/lifecycle/tools/capabilities.ts.source:
/**
 * @file Host capabilities a plugin tool receives at invocation, typed as ports: the host supplies
 * every implementation (token store, guarded HTTP, limiter, artifact store) and Jini never names a
 * provider. A per-call session wraps them so that (1) every capability stops working the moment the
 * plugin's tools are revoked, even for a module that kept a reference, and (2) an access token the
 * call obtained can never leave through the tool's result or error text. Those two gates are
 * `openCapabilityGate`, shared with the admin-surface session so both enforce them identically.
 *
 * Plugin state reaches a tool read-only: the plugin's admin surface writes its settings (for example
 * which of its products are on), and its tools must honor them, but an agent tool never changes them.
 */

/** Options for guarded HTTP; mirrors `@jini-ai/platform`'s guarded fetch, buffered bodies only. */
export interface AgentPluginHttpOptions {
  readonly method?: 'GET' | 'HEAD' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  readonly headers?: Readonly<Record<string, string>>;
  readonly body?: string;
  readonly signal?: AbortSignal;
}

/** Mirrors `@jini-ai/http-kit`'s `RateLimitResult`, so a host can pass its limiter straight through. */
export type AgentPluginLimitResult = { readonly allowed: true } | { readonly allowed: false; readonly retryAfterSeconds: number };

/** Plain JSON a plugin keeps in its plugin- and workspace-scoped state. */
export type AgentPluginStateValue = null | boolean | number | string | readonly AgentPluginStateValue[] | { readonly [key: string]: AgentPluginStateValue };

/**
 * The read-only view of a plugin's own state: what its tools get, and what a host hands any other
 * plugin execution context (form delivery, for example) that must honor the plugin's settings. A
 * host handing it elsewhere passes an object with `get` only, never its whole store.
 */
export interface AgentPluginStateReader {
  get(required: { readonly key: string }, optional?: Record<string, never>): Promise<AgentPluginStateValue | null>;
}

export interface AgentPluginToolCapabilities {
  /** Resolves a fresh access token for a connection the host has scoped to this plugin and workspace.
   *  Never a refresh token. The host refuses a connectionRef the calling plugin does not own. */
  readonly connections: { getAccessToken(required: { readonly connectionRef: string }, optional?: Record<string, never>): Promise<string> };
  /** Outbound HTTP through the host's guarded client (allow-list, redirect refusal, deadlines). */
  readonly http: { fetch(required: { readonly url: string }, optional?: AgentPluginHttpOptions): Promise<Response> };
  /** Plugin-declared budgets; the host keys and sizes them. */
  readonly limiter: { check(required: { readonly key: string }, optional?: Record<string, never>): Promise<AgentPluginLimitResult> };
  /** Stores a file the run can hand to the user; returns an opaque reference, never a path. Absent
   *  when the host has no artifact store, so a tool checks `capabilities.artifacts` before relying on it. */
  readonly artifacts?: { write(required: { readonly name: string; readonly mediaType: string; readonly content: string | Uint8Array }, optional?: Record<string, never>): Promise<{ readonly artifactRef: string }> };
  /** The SAME store the plugin's admin-surface state writes, keyed by the same plugin and workspace
   *  scope. Read-only here: the session exposes `get` alone whatever object the host passes. */
  readonly state: AgentPluginStateReader;
}

/** Context the host uses to scope capabilities: which plugin, which workspace/principal, which call. */
export interface AgentPluginToolCapabilityScope {
  readonly pluginId: string;
  readonly workspaceId: string;
  readonly principalId?: string;
  readonly signal?: AbortSignal;
}

/** Host port: builds the capabilities for one call. Called once per invocation. */
export type AgentPluginToolCapabilitiesPort = (required: AgentPluginToolCapabilityScope, optional?: Record<string, never>) => AgentPluginToolCapabilities;

/** One limit for every reader and writer of plugin state; the admin-surface limits reuse it. */
export const PLUGIN_STATE_MAX_KEY_LENGTH = 128;
const STATE_KEY_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
export const REVOKED_MESSAGE = 'This plugin tool was disabled; its capabilities are revoked. Re-enable the plugin and retry.';
export const WITHHELD_OUTPUT_MESSAGE = 'The plugin tool result was withheld because it contained a connection credential.';
export const WITHHELD_ERROR_MESSAGE = 'The plugin tool failed and its error was withheld because it contained a connection credential.';

/**
 * Access tokens one plugin obtained, across all of its calls: plugin code that keeps a token in module
 * scope must not be able to return or store it in a later call unseen.
 */
export type IssuedTokenMemory = Set<string>;
/** Newest tokens kept; access tokens are short-lived, so older ones matter less than bounded memory. */
export const ISSUED_TOKEN_MEMORY_LIMIT = 64;

/** The host's one source of token memories, passed to its tool projection AND its admin-surface host. */
export interface IssuedTokenMemories {
  forPlugin(required: { readonly pluginId: string }, optional?: Record<string, never>): IssuedTokenMemory;
}

/**
 * One token memory per plugin, shared by every context that runs that plugin's code: its tools, its
 * surface handlers and their state writes. Why per plugin and not per context or generation: those
 * contexts can share module scope (a common lib module), and Node caches an imported module, so its
 * scope outlives a re-sync; a memory per context or per generation would let a token obtained in one
 * leave through the other. A host creates ONE and passes it to both seams.
 * @complexity O(1) per lookup; space O(plugins * ISSUED_TOKEN_MEMORY_LIMIT).
 */
export function createIssuedTokenMemories(_required: Record<string, never> = {}, _optional: Record<string, never> = {}): IssuedTokenMemories {
  const byPlugin = new Map<string, IssuedTokenMemory>();
  return Object.freeze({
    forPlugin({ pluginId }: { readonly pluginId: string }): IssuedTokenMemory {
      let issued = byPlugin.get(pluginId);
      if (issued === undefined) byPlugin.set(pluginId, issued = new Set());
      return issued;
    },
  });
}

/** Records `token` as newest, dropping the oldest beyond the limit. @complexity O(1) amortized. */
function remember(issued: IssuedTokenMemory, token: string): void {
  issued.delete(token);
  issued.add(token);
  if (issued.size > ISSUED_TOKEN_MEMORY_LIMIT) issued.delete(issued.values().next().value!);
}

/** True when `text` holds any issued token, raw or JSON-escaped. @complexity O(n * t). */
function textMentions(text: string, issued: ReadonlySet<string>): boolean {
  for (const token of issued) if (text.includes(token) || text.includes(JSON.stringify(token).slice(1, -1))) return true;
  return false;
}

/** True when `value` (serialized) mentions any issued token. Unserializable values fail closed.
 * @complexity O(n * t) for serialized size n and t issued tokens (t ≤ ISSUED_TOKEN_MEMORY_LIMIT). */
function mentionsToken(value: unknown, issued: ReadonlySet<string>): boolean {
  if (issued.size === 0) return false;
  let text: string | undefined;
  try { text = JSON.stringify(value); } catch { return true; }
  return text !== undefined && textMentions(text, issued);
}

/**
 * Objects an error scan visits before it gives up and withholds the error. Generous for any real
 * error (a few causes, an `AggregateError` of a few dozen), small enough to bound a hostile graph.
 */
const ERROR_SCAN_NODE_LIMIT = 256;

/**
 * Everything one object can hold a token in: every own property, non-enumerable and symbol-keyed
 * ones too (`message`, `stack`, `cause`, `AggregateError.errors`), plus Map and Set contents.
 * Null when reading it threw (a hostile getter or proxy): the caller fails closed.
 * @complexity O(own properties + entries).
 */
function childrenOf(value: object): unknown[] | null {
  try {
    const own = Reflect.ownKeys(value).map(key => (value as Record<PropertyKey, unknown>)[key]);
    if (value instanceof Map) return [...own, ...value.keys(), ...value.values()];
    return value instanceof Set ? [...own, ...value.values()] : own;
  } catch {
    return null;
  }
}

/**
 * True when any string reachable from `error` mentions an issued token. JSON would miss the
 * non-enumerable `cause` and `AggregateError.errors`, and errors held in plain objects, so this walks
 * the object graph instead, to any depth. It fails closed: an unreadable object, or a graph past
 * `ERROR_SCAN_NODE_LIMIT` objects, counts as mentioning a token.
 * @complexity O(v * t) for v visited values (objects bounded by the node limit) and t issued tokens.
 */
function errorMentionsToken(error: unknown, issued: ReadonlySet<string>): boolean {
  if (issued.size === 0) return false;
  const seen = new Set<object>();
  const pending: unknown[] = [error];
  while (pending.length > 0) {
    const next = scanStep(pending.pop(), issued, seen);
    if (next === true) return true;
    // A loop, not push(...next): a huge array would exceed the engine's argument limit.
    for (const child of next) pending.push(child);
  }
  return false;
}

/** One value of the scan: `true` when it mentions a token or cannot be scanned, else what it holds. */
function scanStep(value: unknown, issued: ReadonlySet<string>, seen: Set<object>): true | readonly unknown[] {
  if (typeof value === 'string') return textMentions(value, issued) || [];
  if (typeof value !== 'object' || value === null || seen.has(value)) return [];
  seen.add(value);
  return (seen.size > ERROR_SCAN_NODE_LIMIT ? null : childrenOf(value)) ?? true;
}

/**
 * The credential scans alone, for plugin answers that need no capabilities (a tool's
 * affected-resources disclosure): `mentionsToken`, and `sanitize` (an error, or a credential-free
 * replacement without `cause`, since the cause may hold the token).
 * @param required.issued - The plugin's token memory (see `createIssuedTokenMemories`).
 * @complexity O(1) to open; the scans are O(scanned size * remembered tokens).
 */
export function openCredentialScan(required: { readonly issued: IssuedTokenMemory }, _optional: Record<string, never> = {}) {
  const { issued } = required;
  return {
    mentionsToken: ({ value }: { readonly value: unknown }): boolean => mentionsToken(value, issued),
    sanitize({ error }: { readonly error: unknown }): unknown {
      return errorMentionsToken(error, issued) ? new Error(WITHHELD_ERROR_MESSAGE) : error;
    },
  };
}

export type AgentPluginCredentialScan = ReturnType<typeof openCredentialScan>;

/**
 * The revocation and credential gates every capability session shares: this file's tool session and
 * the admin-surface session (`../../admin-surfaces/surface-capabilities.ts`), so both revoke and scan
 * the same way.
 * @param required.isLive - False once the contributing plugin's contributions are revoked.
 * @param required.issued - The plugin's token memory (see `createIssuedTokenMemories`).
 * @returns `guard` (wraps a capability so it refuses once revoked), `noteToken` (records a token the
 * call obtained), `mentionsToken`, and the `release` (result) and `sanitize` (error) gates.
 * @complexity O(1) to open; the scans are O(serialized size * remembered tokens).
 */
export function openCapabilityGate(required: { readonly isLive: () => boolean; readonly issued: IssuedTokenMemory }, _optional: Record<string, never> = {}) {
  const { isLive, issued } = required;
  return {
    guard: <A extends unknown[], R>(call: (...args: A) => Promise<R>) => async (...args: A): Promise<R> => {
      if (!isLive()) throw new Error(REVOKED_MESSAGE);
      return call(...args);
    },
    noteToken({ token }: { readonly token: string }): string {
      if (token) remember(issued, token);
      return token;
    },
    ...openCredentialScan({ issued }),
    /** The result, unless it mentions a token this plugin obtained. */
    release<T>({ value }: { readonly value: T }): T {
      if (mentionsToken(value, issued)) throw new Error(WITHHELD_OUTPUT_MESSAGE);
      return value;
    },
  };
}

export type AgentPluginCapabilityGate = ReturnType<typeof openCapabilityGate>;
type ArtifactWriteInput = Parameters<NonNullable<AgentPluginToolCapabilities['artifacts']>['write']>[0];

/** The host capabilities every session wraps the same way: guarded HTTP, limiter and artifacts
 * (artifacts only when the host gives a store: absent stays absent, never a wrapper that throws). @complexity O(1). */
export function guardSharedCapabilities(
  required: { readonly gate: AgentPluginCapabilityGate; readonly host: Pick<AgentPluginToolCapabilities, 'http' | 'limiter' | 'artifacts'> },
  _optional: Record<string, never> = {},
): Pick<AgentPluginToolCapabilities, 'http' | 'limiter' | 'artifacts'> {
  const { gate: { guard }, host } = required;
  const { artifacts } = host;
  return {
    http: Object.freeze({ fetch: guard((input: { readonly url: string }, options?: AgentPluginHttpOptions) => host.http.fetch(input, options)) }),
    limiter: Object.freeze({ check: guard((input: { readonly key: string }) => host.limiter.check(input)) }),
    ...(artifacts !== undefined && { artifacts: Object.freeze({ write: guard((input: ArtifactWriteInput) => artifacts.write(input)) }) }),
  };
}

/** The key shape every plugin state call shares, so a key never reaches the host as a path or a scope. */
export function checkedStateKey(required: { readonly key: unknown }, _optional: Record<string, never> = {}): string {
  const { key } = required;
  if (typeof key !== 'string' || !STATE_KEY_PATTERN.test(key)) throw new Error(`A settings key must be a short name of at most ${PLUGIN_STATE_MAX_KEY_LENGTH} characters.`);
  return key;
}

/**
 * The read-only state view a session hands out: `get` alone, the key checked and passed on by itself
 * (so plugin code cannot add a scope the host might honor), revoked with the session's gate.
 * @complexity O(1) plus the key check.
 */
export function guardStateReader(required: { readonly gate: AgentPluginCapabilityGate; readonly state: AgentPluginStateReader }, _optional: Record<string, never> = {}): AgentPluginStateReader {
  const { gate, state } = required;
  return Object.freeze({ get: gate.guard(({ key }: { readonly key: string }) => state.get({ key: checkedStateKey({ key }) })) });
}

/**
 * Opens the capability session for one tool call.
 * @param required.capabilities - The host's capabilities for this call.
 * @param required.isLive - False once the contributing plugin's tools are revoked.
 * @param required.issued - The plugin's token memory, shared by all its calls and its surface handlers.
 * @returns Wrapped capabilities plus `release` (result gate) and `sanitize` (error gate).
 * @complexity O(1) to open; gates are O(serialized size).
 */
export function openCapabilitySession(
  required: { readonly capabilities: AgentPluginToolCapabilities; readonly isLive: () => boolean; readonly issued: IssuedTokenMemory },
  _optional: Record<string, never> = {},
) {
  const { capabilities: host, isLive, issued } = required;
  const gate = openCapabilityGate({ isLive, issued });
  const capabilities: AgentPluginToolCapabilities = Object.freeze({
    connections: Object.freeze({ getAccessToken: gate.guard(async (input: { readonly connectionRef: string }) =>
      gate.noteToken({ token: await host.connections.getAccessToken({ connectionRef: input.connectionRef }) })) }),
    ...guardSharedCapabilities({ gate, host }),
    state: guardStateReader({ gate, state: host.state }),
  });
  return { capabilities, release: gate.release, sanitize: gate.sanitize };
}

