test("a decompression bomb (actual bytes exceed the declared size) is caught while streaming, not after", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-bomb"));
    const digest = createHash("sha256").update(archive).digest("hex");

    // Declares a tiny size, but the read stream actually yields far more — the lie a real
    // compressed bomb tells. The per-file byte cap must be enforced against bytes ACTUALLY
    // observed leaving the "decompressor" (this fake stream), not the declared/trusted size.
    let chunksConsumed = 0;
    let streamClosed = false;
    const bomb: AgentPluginArchiveEntry = {
      kind: "file",
      entryPath: "skills/a/SKILL.md",
      declaredSize: 10,
      executable: false,
      async *openReadStream() {
        const chunk = new Uint8Array(1024 * 1024); // 1 MiB per chunk
        try {
          for (let i = 0; i < 64; i += 1) {
            chunksConsumed += 1;
            yield chunk; // 64 MiB actual, far past the 16 MiB per-file cap
          }
        } finally {
          streamClosed = true;
        }
      },
    } as AgentPluginArchiveEntry;

    await assert.rejects(
      () =>
        installAgentPlugin({
          archive,
          expectedSha256: digest,
          archiveReader: reader([fileEntry("plugin.json", VALID_MANIFEST), bomb]),
          layout: instanceLayout,
          workspaceId: WORKSPACE_ID,
        }),
      (error: unknown) => error instanceof AgentPluginInstallError && error.code === "DECOMPRESSION_BOMB",
    );
    assert.equal(chunksConsumed, 17, "stop at the first chunk crossing the 16 MiB cap");
    assert.equal(streamClosed, true, "the decompressor must be closed on early rejection");
    assert.deepEqual(await readdir(layout.root), ["staging"], "rejection must not create a plugin/package directory");
    assert.deepEqual(await readdir(layout.staging), [], "rejection must remove the staging transaction");
  } finally {
    await forceRemove(cwd);
  }
});

test("the total-extracted-bytes cap is enforced across many small files (the 'many files' bomb variant)", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-many-files"));
    const digest = createHash("sha256").update(archive).digest("hex");

    // Reuse one chunk instead of allocating 200 MiB. The real ZIP suite covers disk throughput;
    // this unit keeps real containment/open/cleanup but counts payload writes through the fs port.
    const chunk = Buffer.alloc(1024 * 1024, 120); // 1 MiB per file
    let chunksConsumed = 0;
    let streamsClosed = 0;
    let payloadBytesAccepted = 0;
    let payloadHandlesClosed = 0;
    const { installAgentPlugin: installWithCountingSink } = createInstallModule({
      ...ports,
      filesystem: { ...ports.filesystem, open: async (filename, flags, mode) => {
        const handle = await ports.filesystem.open(filename, flags, mode);
        if (path.basename(String(filename)) === "plugin.json") return handle;
        return {
          async write(bytes: Uint8Array) {
            payloadBytesAccepted += bytes.byteLength;
            return { bytesWritten: bytes.byteLength, buffer: bytes };
          },
          async close() {
            await handle.close();
            payloadHandlesClosed += 1;
          },
        } as unknown as Awaited<ReturnType<typeof ports.filesystem.open>>;
      } },
    });
    const manyEntries: AgentPluginArchiveEntry[] = [fileEntry("plugin.json", VALID_MANIFEST)];
    for (let i = 0; i < 200; i += 1) manyEntries.push(fileEntry(`skills/a/refs/f${i}.md`, "", {
      declaredSize: chunk.byteLength,
      async *openReadStream() {
        try {
          chunksConsumed += 1;
          yield chunk;
        } finally {
          streamsClosed += 1;
        }
      },
    }));

    await assert.rejects(
      () =>
        installWithCountingSink({
          archive,
          expectedSha256: digest,
          archiveReader: reader(manyEntries),
          layout: instanceLayout,
          workspaceId: WORKSPACE_ID,
        }),
      (error: unknown) => error instanceof AgentPluginInstallError && error.code === "TOTAL_SIZE_EXCEEDED"
        && error.message === "archive exceeds the 67108864-byte total extracted-size cap",
    );
    assert.equal(chunksConsumed, 64, "manifest bytes make the 64th 1 MiB payload cross the aggregate cap");
    assert.equal(payloadBytesAccepted, 63 * 1024 * 1024, "the first over-cap chunk must never reach the write sink");
    assert.equal(streamsClosed, 64, "every opened decompressor must close, including the rejected stream");
    assert.equal(payloadHandlesClosed, 64, "every payload handle must close before staging cleanup");
    assert.deepEqual(await readdir(layout.root), ["staging"], "rejection must not create a plugin/package directory");
    assert.deepEqual(await readdir(layout.staging), [], "rejection must remove the staging transaction");
  } finally {
    await forceRemove(cwd);
  }
});

test("the entry-count cap is enforced before any entry is extracted", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-many-entries"));
    const digest = createHash("sha256").update(archive).digest("hex");

    // Counts content reads: the "million small files" archive must be refused from entry metadata
    // alone, not after the cap's worth of files has already been written to staging.
    let streamsOpened = 0;
    const countedFile = (entryPath: string, content: string): AgentPluginArchiveEntry => {
      const entry = fileEntry(entryPath, content);
      return {
        ...entry,
        openReadStream(options: Record<string, never>) {
          streamsOpened += 1;
          return (entry as Extract<AgentPluginArchiveEntry, { kind: "file" }>).openReadStream(options);
        },
      } as AgentPluginArchiveEntry;
    };
    const manyEntries: AgentPluginArchiveEntry[] = [countedFile("plugin.json", VALID_MANIFEST)];
    for (let i = 0; i < 5000; i += 1) manyEntries.push(countedFile(`skills/a/refs/f${i}.md`, "x"));

    await assert.rejects(
      () =>
        installAgentPlugin({
          archive,
          expectedSha256: digest,
          archiveReader: reader(manyEntries),
          layout: instanceLayout,
          workspaceId: WORKSPACE_ID,
        }),
      (error: unknown) => error instanceof AgentPluginInstallError && error.code === "TOO_MANY_ENTRIES",
    );
    assert.equal(streamsOpened, 0, "an over-cap archive must be rejected before any entry content is read");
    assert.deepEqual(await readdir(layout.root), ["staging"], "rejection must not create a plugin/package directory");
    assert.deepEqual(await readdir(layout.staging), [], "rejection must remove the staging transaction");
  } finally {
    await forceRemove(cwd);
  }
});

test("a SHA-256 digest mismatch is rejected before any extraction is attempted", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  let extractionAttempted = false;
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-digest-mismatch"));
    const wrongDigest = "0".repeat(64);

    const spyReader: AgentPluginArchiveReaderPort = {
      async *entries() {
        extractionAttempted = true;
        yield* validPackageEntries();
      },
    };

    await assert.rejects(
      () =>
        installAgentPlugin({
          archive,
          expectedSha256: wrongDigest,
          archiveReader: spyReader,
          layout: instanceLayout,
          workspaceId: WORKSPACE_ID,
        }),
      (error: unknown) => error instanceof AgentPluginInstallError && error.code === "DIGEST_MISMATCH",
    );
    assert.equal(extractionAttempted, false, "extraction must never run against unverified bytes");
  } finally {
    await forceRemove(cwd);
  }
});

test("installing the identical archive twice stages twice but never refreezes the published package (Layout B dedup)", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-dedup"));
    const digest = createHash("sha256").update(archive).digest("hex");

    const { reader: countingReader, extractions } = extractionCountingReader();
    let freezeWrites = 0;
    const { installAgentPlugin: installWithFreezeCounter } = createInstallModule({
      ...ports,
      filesystem: { ...ports.filesystem, chmod: (async (filename, mode) => {
        if (String(filename).includes(`/package/sha256/${digest}`)) freezeWrites++;
        return ports.filesystem.chmod(filename, mode);
      }) as typeof ports.filesystem.chmod },
    });

    const first = await installWithFreezeCounter({
      archive,
      expectedSha256: digest,
      archiveReader: countingReader,
      layout: instanceLayout,
      workspaceId: WORKSPACE_ID,
    });
    const firstFreezeWrites = freezeWrites;
    assert.ok(firstFreezeWrites > 0, "the first publication must really freeze its package");
    const second = await installWithFreezeCounter({
      archive,
      expectedSha256: digest,
      archiveReader: countingReader,
      layout: instanceLayout,
      workspaceId: WORKSPACE_ID,
    });

    // Layout B must extract to learn the manifest id before it can choose a per-plugin destination.
    assert.equal(extractions(), 2, "each install must perform exactly one bounded staging extraction");
    assert.equal(freezeWrites, firstFreezeWrites, "dedup must not rewrite the published package's permissions");
    assert.deepEqual(second, first, "dedup must return exactly the original installed package");
    assert.equal(first.packageRoot, second.packageRoot);
  } finally {
    await forceRemove(cwd);
  }
});

test("explicit directory entries are extracted and excluded from the file index", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-directories"));
    const digest = createHash("sha256").update(archive).digest("hex");
    const installed = await installAgentPlugin({
      archive, expectedSha256: digest, layout: instanceLayout, workspaceId: WORKSPACE_ID,
      archiveReader: reader([
        { kind: "directory", entryPath: "skills/" },
        { kind: "directory", entryPath: "skills/ui-ux-design/" },
        { kind: "directory", entryPath: "empty/" },
        ...validPackageEntries(),
      ]),
    });
    assert.deepEqual(installed.files, ["plugin.json", "skills/ui-ux-design/SKILL.md"]);
    assert.deepEqual(installed.skills, [{ name: "ui-ux-design", skillPath: "skills/ui-ux-design/SKILL.md" }]);
    assert.equal((await stat(path.join(installed.packageRoot, "empty"))).isDirectory(), true);
    assert.deepEqual(await readdir(layout.pluginPackagesDir({ pluginId: "ui-ux-design" })), [digest]);
    assert.deepEqual(await readdir(layout.staging), []);
  } finally {
    await forceRemove(cwd);
  }
});

test("an in-flight install recovers when another install publishes the same digest first", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  let release!: () => void;
  const held = new Promise<void>((resolve) => { release = resolve; });
  let entered!: () => void;
  const extracting = new Promise<void>((resolve) => { entered = resolve; });
  let losingInstall: ReturnType<typeof installAgentPlugin> | undefined;
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-publication-race"));
    const digest = createHash("sha256").update(archive).digest("hex");
    losingInstall = installAgentPlugin({
      archive, expectedSha256: digest, layout: instanceLayout, workspaceId: WORKSPACE_ID,
      archiveReader: { async *entries() { entered(); await held; yield* validPackageEntries(); } },
    });
    await extracting; // The loser owns staging setup; Layout B checks dedup after extraction.
    const winner = await installAgentPlugin({
      archive, expectedSha256: digest, layout: instanceLayout, workspaceId: WORKSPACE_ID,
      archiveReader: reader(validPackageEntries()),
    });
    release();
    const loser = await losingInstall;
    assert.deepEqual(loser, winner);
    assert.equal(await readFile(path.join(loser.packageRoot, "plugin.json"), "utf8"), VALID_MANIFEST);
    assert.deepEqual(await readdir(layout.pluginPackagesDir({ pluginId: "ui-ux-design" })), [digest]);
    assert.deepEqual(await readdir(layout.staging), []);
    assert.equal((await stat(loser.packageRoot)).mode & 0o777, 0o555);
  } finally {
    release();
    await losingInstall?.catch(() => undefined);
    await forceRemove(cwd);
  }
});

