import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import * as filesystem from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { test } from 'vitest';
import { createAgentPluginLifecycle, createAgentPluginLayout, type AgentPluginArchiveReaderPort } from '../../index.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

const workspaceId = 'workspace-a';
const pluginId = 'reconciled-plugin';
function packageInput(layout: ReturnType<typeof createAgentPluginLayout>) {
  const archive = Buffer.from('reconciled-package');
  const files = {
    'plugin.json': JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: pluginId,
      extensions: { 'org.example.host': { displayName: `  ${'D'.repeat(80)}  `, summary: `  First\n\n${'S'.repeat(1300)}  ` } } }),
    [`skills/${pluginId}/SKILL.md`]: '# Reconciled plugin\n',
  };
  const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
    for (const [entryPath, text] of Object.entries(files)) yield { kind: 'file', entryPath,
      declaredSize: Buffer.byteLength(text), openReadStream: async function* () { yield Buffer.from(text); } };
  } };
  return { archive, archiveReader, expectedSha256: createHash('sha256').update(archive).digest('hex'), layout, workspaceId };
}

test('the host namespace controls capped display text on real install and dedup output', async () => {
  const root = await filesystem.mkdtemp(path.join(os.tmpdir(), 'lifecycle-display-'));
  const layout = createAgentPluginLayout({ root });
  try {
    const baseline = createAgentPluginLifecycle({ ...ports, layout, extensionNamespace: 'org.example.other' });
    const treatment = createAgentPluginLifecycle({ ...ports, layout, extensionNamespace: 'org.example.host' });
    const input = packageInput(layout);
    const before = await baseline.installAgentPlugin(input);
    const after = await treatment.installAgentPlugin(input);
    // Identical bytes and paths isolate namespace policy; assertions inspect the installed read model.
    assert.equal(after.packageRoot, before.packageRoot);
    assert.equal(Object.hasOwn(before, 'displayName'), false);
    assert.equal(Object.hasOwn(before, 'summary'), false);
    assert.equal(after.displayName, 'D'.repeat(64));
    assert.equal(after.summary, `First\n\n${'S'.repeat(1300)}`.slice(0, 1200));
  } finally { await forceRemove(root); }
});

test('preview validates bytes but publishes no package or persistent memory', async () => {
  const root = await filesystem.mkdtemp(path.join(os.tmpdir(), 'lifecycle-preview-'));
  const layout = createAgentPluginLayout({ root });
  const api = createAgentPluginLifecycle({ ...ports, layout });
  try {
    const input = packageInput(layout);
    const preview = await api.installAgentPlugin(input, { previewOnly: true,
      publishGuard: async () => { throw new Error('preview must not invoke publication policy'); } });
    assert.equal(preview.pluginId, pluginId);
    const workspace = layout.forWorkspace({ workspaceId });
    await assert.rejects(filesystem.stat(preview.packageRoot), { code: 'ENOENT' });
    await assert.rejects(filesystem.stat(workspace.pluginRootDir({ pluginId })), { code: 'ENOENT' });
    assert.deepEqual(await filesystem.readdir(workspace.staging), []);
    const installed = await api.installAgentPlugin(input);
    assert.equal((await filesystem.stat(installed.packageRoot)).isDirectory(), true);
  } finally { await forceRemove(root); }
});

test('publication policy runs under the plugin lock and refusal leaves no published state', async () => {
  const root = await filesystem.mkdtemp(path.join(os.tmpdir(), 'lifecycle-guard-'));
  const layout = createAgentPluginLayout({ root });
  const api = createAgentPluginLifecycle({ ...ports, layout });
  const refusal = new Error('host publication refused');
  try {
    const input = packageInput(layout);
    const workspace = layout.forWorkspace({ workspaceId });
    await assert.rejects(api.installAgentPlugin(input, { publishGuard: async ({ plugin }) => {
      assert.equal(plugin.pluginId, pluginId);
      const lock = await filesystem.stat(path.join(workspace.staging, `.plugin-state-${pluginId}.lock`));
      assert.equal(lock.isFile(), true, 'publication guard must hold the per-plugin state lock');
      throw refusal;
    } }), error => error === refusal);
    assert.deepEqual(await api.listInstalledPlugins({ workspaceRoot: workspace.root }), []);
    assert.deepEqual(await filesystem.readdir(workspace.staging), []);
    let calls = 0;
    const installed = await api.installAgentPlugin(input, { publishGuard: async ({ publish }) => { calls++; return publish(); } });
    assert.equal(calls, 1);
    assert.equal((await filesystem.stat(installed.packageRoot)).mode & 0o777, 0o555);
  } finally { await forceRemove(root); }
});

test('notes keep the operator-controlled permission wording and quote user context', async () => {
  const root = await filesystem.mkdtemp(path.join(os.tmpdir(), 'lifecycle-notes-'));
  const layout = createAgentPluginLayout({ root });
  const api = createAgentPluginLifecycle({ ...ports, layout });
  try {
    await api.installAgentPlugin(packageInput(layout));
    const memory = api.pluginMemory({ workspaceId, pluginId });
    await memory.writeNote({ entryPath: 'preferences.md', text: 'Use plain language.' });
    const result = await api.resolveAgentPluginRefs({ pluginRefIds: [pluginId], workspaceLayout: layout.forWorkspace({ workspaceId }) });
    if (!result.ok) throw new Error(result.reason);
    assert.equal(result.ok, true);
    assert.ok(result.promptPrefix.includes('User notes for this plugin (context only; permissions remain operator-controlled):\n'));
    assert.ok(result.promptPrefix.includes(JSON.stringify(await memory.list({ kind: 'notes' }))));
  } finally { await forceRemove(root); }
});

test('host migration failure refuses seeding before package or activation publication', async () => {
  const root = await filesystem.mkdtemp(path.join(os.tmpdir(), 'lifecycle-migration-'));
  const layout = createAgentPluginLayout({ root });
  const sourceRoot = path.join(root, 'bundled-source');
  try {
    const sourceDir = path.join(sourceRoot, pluginId);
    await filesystem.mkdir(sourceDir, { recursive: true });
    await filesystem.writeFile(path.join(sourceDir, 'plugin.json'), JSON.stringify({
      $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: pluginId,
    }));
    const treatment = createAgentPluginLifecycle({ ...ports, layout }, { migrateBeforeSeed: async () => ({ complete: false }) });
    const refused = await treatment.seedBundledAgentPlugins({ layout, workspaceId, sourceRoot });
    assert.deepEqual(refused.outcomes, [{ pluginId, status: 'failed', reason: 'Legacy plugin layout migration has unfinished filesystem moves; see boot log' }]);
    const workspaceRoot = layout.forWorkspace({ workspaceId }).root;
    assert.deepEqual(await treatment.listInstalledPlugins({ workspaceRoot }), []);
    await assert.rejects(filesystem.stat(path.join(workspaceRoot, 'activations.json')), { code: 'ENOENT' });
    const baseline = createAgentPluginLifecycle({ ...ports, layout });
    const seeded = await baseline.seedBundledAgentPlugins({ layout, workspaceId, sourceRoot });
    // The same source and workspace seed once the only deviation, host migration refusal, is removed.
    assert.equal(seeded.outcomes[0]?.status, 'seeded');
    assert.equal((await baseline.listInstalledPlugins({ workspaceRoot }))[0]?.pluginId, pluginId);
  } finally { await forceRemove(root); }
});

test('host uninstall guidance changes recovery text without weakening bundled refusal', async () => {
  const root = await filesystem.mkdtemp(path.join(os.tmpdir(), 'lifecycle-recovery-'));
  const layout = createAgentPluginLayout({ root });
  const baseline = createAgentPluginLifecycle({ ...ports, layout });
  const treatment = createAgentPluginLifecycle({ ...ports, layout }, {
    formatBundledUninstallRecovery: () => 'used, disable it in the host control panel.',
  });
  try {
    const installed = await baseline.installAgentPlugin(packageInput(layout));
    const workspaceRoot = layout.forWorkspace({ workspaceId }).root;
    await baseline.recordBundledAgentPluginIfAbsent({ workspaceRoot, pluginId });
    const refusal = (ending: string) => (error: unknown) => error instanceof Error && error.message ===
      `Agent Plugin '${pluginId}' is bundled with the host and cannot be uninstalled — it is re-seeded on every boot ` +
      '(seed-bundled.ts), so removing its files now would silently reappear on the next restart. To stop it being ' + ending;
    const input = { layout, workspaceId, pluginId };
    await assert.rejects(baseline.uninstallAgentPlugin(input), refusal("used, disable it through the host's activation control."));
    await assert.rejects(treatment.uninstallAgentPlugin(input), refusal('used, disable it in the host control panel.'));
    // Identical installed state remains protected in both variants; only operator recovery wording differs.
    assert.equal((await filesystem.stat(installed.packageRoot)).isDirectory(), true);
    assert.equal((await baseline.readAgentPluginActivations({ workspaceRoot })).plugins[pluginId]?.origin, 'bundled');
  } finally { await forceRemove(root); }
});

/** Crash-point harness: snapshot the workspace after every durable effect (rename, chmod, rm and
 * MCP provisioning) while `capture` is on, then replay each snapshot as a fresh process. */
async function crashHarness(prefix: string, { failCandidateMcp = false } = {}) {
  const temp = await filesystem.mkdtemp(path.join(os.tmpdir(), prefix));
  const layout = createAgentPluginLayout({ root: path.join(temp, 'original') });
  const workspace = layout.forWorkspace({ workspaceId });
  const snapshots: string[] = [];
  const control = { capture: false };
  const checkpoint = async () => {
    if (!control.capture) return;
    const directory = path.join(temp, `checkpoint-${snapshots.length}`);
    await filesystem.cp(workspace.root, directory, { recursive: true, preserveTimestamps: true });
    snapshots.push(directory);
  };
  const effects = { ...filesystem,
    rename: (async (from, to) => { await filesystem.rename(from, to); await checkpoint(); }) as typeof filesystem.rename,
    chmod: (async (file, mode) => { await filesystem.chmod(file, mode); await checkpoint(); }) as typeof filesystem.chmod,
    rm: (async (target, options) => { await filesystem.rm(target, options); await checkpoint(); }) as typeof filesystem.rm,
  };
  const mcpProvisioning = { ...ports.mcpProvisioning, provision: async ({ installed }: { installed: { version?: string | undefined } }) => {
    await checkpoint();
    if (failCandidateMcp && installed.version === '2.0.0') throw new Error('candidate MCP failed');
  } };
  const api = createAgentPluginLifecycle({ ...ports, layout, filesystem: effects, mcpProvisioning });
  const input = (version: string) => {
    const archive = Buffer.from(`crash-boundary-${version}`);
    const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
      yield { kind: 'file', entryPath: 'plugin.json', openReadStream: async function* () { yield Buffer.from(JSON.stringify({
        $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: pluginId, version,
      })); } };
    } };
    return { archive, expectedSha256: createHash('sha256').update(archive).digest('hex'), archiveReader, layout, workspaceId };
  };
  const previous = await api.installAgentPlugin(input('1.0.0'));
  await api.setAgentPluginActivation({ workspaceRoot: workspace.root, pluginId, enabled: true, actor: 'owner' });
  const update = () => api.updateAgentPlugin({ ...input('2.0.0'), pluginId, expectedOldDigest: previous.archiveDigest, actor: 'owner', snapshotSettings: async () => ({ values: [] }) });
  return { temp, api, snapshots, control, update, previous, workspace };
}

/** The durable stage a snapshot reached: the active journal's state, or `filed` once the
 * committed audit is in the history and the journal is gone. */
async function durableStage(snapshot: string): Promise<string> {
  try { return JSON.parse(await filesystem.readFile(path.join(snapshot, pluginId, 'update-journal.json'), 'utf8')).state; }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
  let filed: string[] = [];
  try { filed = await filesystem.readdir(path.join(snapshot, pluginId, 'update-history')); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
  for (const name of filed) {
    if (JSON.parse(await filesystem.readFile(path.join(snapshot, pluginId, 'update-history', name), 'utf8')).result === 'updated') return 'filed';
  }
  return 'before-intent';
}

/** Boots a fresh process on each snapshot and asserts one enabled revision of the expected version,
 * no retained rollback bytes, and an idempotent second boot. Returns the stages seen. */
async function replayEverySnapshot({ temp, snapshots, expectedVersion }: { temp: string; snapshots: readonly string[]; expectedVersion: (stage: string) => string }) {
  const stages = new Set<string>();
  for (const [index, snapshot] of snapshots.entries()) {
    const replayLayout = createAgentPluginLayout({ root: path.join(temp, `replay-${index}`) });
    const replayWorkspace = replayLayout.forWorkspace({ workspaceId });
    await filesystem.mkdir(path.dirname(replayWorkspace.root), { recursive: true });
    await filesystem.cp(snapshot, replayWorkspace.root, { recursive: true });
    // The captured process is gone. Discard its lock files, not its recovery journal or bytes.
    for (const name of await filesystem.readdir(replayWorkspace.root)) {
      if (name.endsWith('.lock')) await filesystem.rm(path.join(replayWorkspace.root, name), { force: true });
    }
    await forceRemove(replayWorkspace.staging);
    const stage = await durableStage(snapshot);
    stages.add(stage);
    const replay = createAgentPluginLifecycle({ ...ports, layout: replayLayout });
    await replay.reconcileAgentPluginUpdates({ workspaceId });
    const installed = await replay.listInstalledPlugins({ workspaceRoot: replayWorkspace.root });
    assert.deepEqual(installed.map(plugin => plugin.version), [expectedVersion(stage)], `snapshot ${index} (${stage})`);
    assert.equal((await replay.resolveAgentPluginActivation({ workspaceRoot: replayWorkspace.root, pluginId })).verdict, 'active');
    assert.deepEqual(await filesystem.readdir(path.join(replayWorkspace.root, pluginId, 'rollback')).catch(() => []), []);
    await replay.reconcileAgentPluginUpdates({ workspaceId });
    assert.equal((await replay.listInstalledPlugins({ workspaceRoot: replayWorkspace.root })).length, 1);
  }
  return stages;
}

test('every durable update switch boundary recovers to one enabled revision after process death', async () => {
  const h = await crashHarness('update-crash-boundaries-');
  try {
    // Removing a retained stale copy of the old digest is the only effect before intent is recorded
    // (it runs only when such a copy exists), so plant one to capture that boundary too.
    await filesystem.cp(h.previous.packageRoot, path.join(h.workspace.pluginRootDir({ pluginId }), 'rollback', h.previous.archiveDigest), { recursive: true });
    h.control.capture = true;
    await h.update();
    h.control.capture = false;
    assert.ok(h.snapshots.length > 10, 'capture stage, publish, freeze, journal switch, activation and MCP boundaries');
    const committed = (stage: string) => stage === 'committed' || stage === 'filed';
    const stages = await replayEverySnapshot({ ...h, expectedVersion: stage => committed(stage) ? '2.0.0' : '1.0.0' });
    for (const stage of ['before-intent', 'pending', 'published', 'committed', 'filed']) assert.ok(stages.has(stage), stage);
  } finally { await forceRemove(h.temp); }
});

test('a process death at any point of an in-process rollback still boots into the old revision', async () => {
  const h = await crashHarness('update-crash-rollback-', { failCandidateMcp: true });
  try {
    h.control.capture = true;
    await assert.rejects(h.update(), /candidate MCP failed/);
    h.control.capture = false;
    const stages = await replayEverySnapshot({ ...h, expectedVersion: () => '1.0.0' });
    for (const stage of ['pending', 'published']) assert.ok(stages.has(stage), stage);
  } finally { await forceRemove(h.temp); }
});

test('a process death while boot collects retained rollback bytes is finished by the next boot', async () => {
  const h = await crashHarness('update-crash-cleanup-');
  try {
    await h.update();
    h.control.capture = true;
    await h.api.reconcileAgentPluginUpdates({ workspaceId });
    h.control.capture = false;
    assert.ok(h.snapshots.length > 1, 'capture the unfreeze and removal of the rollback tree');
    const stages = await replayEverySnapshot({ ...h, expectedVersion: () => '2.0.0' });
    assert.deepEqual([...stages], ['filed']);
  } finally { await forceRemove(h.temp); }
});

src/lifecycle/tools/__tests__/agent-plug.source:
/**
 * @file Security pins for executable Agent Plugin tools (phase A): admission refusals through the real
 * trust gate (inactive, tampered digest, path escape, duplicate id), projection refusals (ambiguous id,
 * undisclosed write, unusable schema), schema refusal of bad input, credential containment of results
 * and errors, destructive confirmation, and revocation on disable.
 */
import { expect, test } from 'vitest';
import { ToolInputError } from '@jini-ai/core';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { ISSUED_TOKEN_MEMORY_LIMIT, openCapabilityGate, openCapabilitySession, REVOKED_MESSAGE, WITHHELD_ERROR_MESSAGE, WITHHELD_OUTPUT_MESSAGE, type AgentPluginToolCapabilities, createIssuedTokenMemories } from '../capabilities.js';
import type { LoadedAgentPluginTool } from '../definition.js';
import { createAgentPluginToolProjection } from '../projection.js';
import { setAgentPluginActivation } from '../../__tests__/test-support.js';
import { createHarness, FAKE_TOKEN, fakeCapabilities, installPlugin, toolsFile, TOOLS_FILENAME, withWorkspace } from './support.js';

const SCHEMA = { type: 'object', required: ['ref'], additionalProperties: false, properties: { ref: { type: 'string' } } };
const READ_MODULE = 'export default { invoke: ({ input }) => ({ read: input.ref }) };\n';
const declare = (overrides: Record<string, unknown> = {}) => ({ name: 'look', description: 'Look.', effect: 'read', module: 'tools/look.mjs', inputSchema: SCHEMA, ...overrides });

async function loadOne(files: Record<string, string>, optional: { enabled?: boolean; bundled?: boolean } = {}) {
  return withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'fixture-tools', files }, optional);
    const harness = createHarness();
    const refusals = await harness.refresh();
    return { refusals, registered: harness.tools.has({ toolId: 'p_fixture_tools__look' }) };
  });
}

test('an inactive plugin contributes no tool and is skipped silently', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare()]), 'tools/look.mjs': READ_MODULE }, { enabled: false }))
    .toEqual({ refusals: [], registered: false });
});

test('a package whose digest is not the bundled one is refused', async () => {
  const { refusals, registered } = await loadOne({ [TOOLS_FILENAME]: toolsFile([declare()]), 'tools/look.mjs': READ_MODULE }, { bundled: false });
  expect(registered).toBe(false);
  expect(refusals).toHaveLength(1);
  expect(refusals[0]).toMatch(/^agent tools from 'fixture-tools' were not loaded: only plugins shipped with the host may add agent tools \(installed digest [0-9a-f]{12} is not the one this build shipped\)$/);
});

test('a module path that escapes the plugin root is refused before import', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare({ module: '../outside.mjs' })]) })).toEqual({
    refusals: ["agent tool 'look' from 'fixture-tools' was not loaded: module path '../outside.mjs' escapes the plugin root"], registered: false });
});

test('a non-.mjs module path is refused by the parser', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare({ module: 'tools/look.js' })]) })).toEqual({
    refusals: [`agent tools from 'fixture-tools' were not loaded: ${TOOLS_FILENAME} is invalid: tool 'look' module must be a .mjs path inside the plugin`], registered: false });
});

test('a local name declared twice refuses the whole file (duplicate id)', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare(), declare()]), 'tools/look.mjs': READ_MODULE })).toEqual({
    refusals: [`agent tools from 'fixture-tools' were not loaded: ${TOOLS_FILENAME} is invalid: tool 'look' is declared more than once`], registered: false });
});

const loaded = (pluginId: string, overrides: Partial<LoadedAgentPluginTool['descriptor']> = {}, module: LoadedAgentPluginTool['module'] = { invoke: () => 'ok' }): LoadedAgentPluginTool => ({
  pluginId, module, descriptor: { name: 'look', description: 'Look.', effect: 'read', module: 'tools/look.mjs', inputSchema: SCHEMA, ...overrides },
});
function projectionFor(capabilities: AgentPluginToolCapabilities = fakeCapabilities({ tokenRequests: [], requests: [] })) {
  const registry = createPluginContributionRegistry({});
  return { registry, projection: createAgentPluginToolProjection({ issuedTokens: createIssuedTokenMemories(), registry, toolIdFor: pluginToolIdFor, capabilities: () => capabilities }) };
}

test.each([['a-b', 'a_b'], ['a_b', 'a-b']])('two plugins whose namespaced ids collide are both refused (ambiguous): %s, %s', (first, second) => {
  const { registry, projection } = projectionFor();
  expect(projection.sync({ loaded: [loaded(first), loaded(second)], refusals: [] }).refusals)
    .toEqual(["agent tool 'p_a_b__look' was not loaded: more than one plugin declares it ('a-b', 'a_b')"]);
  expect(registry.list({})).toEqual([]);
});

test('a write or destructive tool without describeAffectedResources is refused', () => {
  const { projection } = projectionFor();
  expect(projection.sync({ loaded: [loaded('p', { effect: 'write' }), loaded('q', { effect: 'destructive' })], refusals: [] }).refusals).toEqual([
    "agent tool 'look' from 'p' was not loaded: a write tool must export describeAffectedResources()",
    "agent tool 'look' from 'q' was not loaded: a destructive tool must export describeAffectedResources()",
  ]);
});

test('an input schema the validator cannot compile is refused', () => {
  const { projection } = projectionFor();
  const [refusal] = projection.sync({ loaded: [loaded('p', { inputSchema: { type: 'object', $ref: '#/missing' } })], refusals: [] }).refusals;
  expect(refusal).toMatch(/^agent tool 'look' from 'p' was not loaded: its input schema is invalid \(/);
});

test('a schema fault reached only by some inputs fails closed as a plugin fault, not bad input', async () => {
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', { inputSchema: { type: 'object', properties: { ref: { type: 'string', pattern: '(' } } } })], refusals: [] });
  const snapshot = registry.list({})[0]!;
  const call = snapshot.tools[0]!.handler({ pluginId: 'p', sdk: snapshot.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'x' } });
  await expect(call).rejects.toThrow("Plugin tool 'p_p__look' has an unusable input schema; report it to the plugin author.");
  await expect(call).rejects.not.toBeInstanceOf(ToolInputError);
});

test('input that fails the schema is refused before the module runs, naming locations not values', async () => {
  const calls: unknown[] = [];
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', {}, { invoke: (input) => { calls.push(input); return 'ran'; } })], refusals: [] });
  const tool = registry.list({})[0]!.tools[0]!;
  const call = tool.handler({ pluginId: 'p', sdk: registry.list({})[0]!.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'secret-value', extra: 1 } });
  await expect(call).rejects.toBeInstanceOf(ToolInputError);
  await expect(call).rejects.toThrow("Input for 'p_p__look' does not match its schema at");
  await expect(call).rejects.not.toThrow('secret-value');
  expect(calls).toEqual([]);
  await expect(projection.describeAffectedResources({ toolId: 'p_p__look', input: { ref: 7 } })).rejects.toBeInstanceOf(ToolInputError);
});

async function runWith(module: LoadedAgentPluginTool['module']) {
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', {}, module)], refusals: [] });
  const snapshot = registry.list({})[0]!;
  return snapshot.tools[0]!.handler({ pluginId: 'p', sdk: snapshot.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'c1' } });
}

test('a result that contains an issued access token is withheld', async () => {
  await expect(runWith({ invoke: async ({ capabilities }) => ({ leaked: await capabilities.connections.getAccessToken({ connectionRef: 'c1' }) }) }))
    .rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test('a token the module kept from an EARLIER call of the same generation is withheld', async () => {
  let kept = '';
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', {}, { invoke: async ({ capabilities }) => {
    if (kept === '') { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { first: true }; }
    return { leaked: kept };
  } })], refusals: [] });
  const call = () => registry.list({})[0]!.tools[0]!.handler({ pluginId: 'p', sdk: registry.list({})[0]!.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'c1' } });
  await call();
  await expect(call()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test('the remembered tokens are bounded: the oldest of more than 64 falls out, the newest stays', async () => {
  const issued = new Set<string>();
  const gate = openCapabilityGate({ isLive: () => true, issued });
  for (let index = 0; index <= ISSUED_TOKEN_MEMORY_LIMIT; index += 1) gate.noteToken({ token: `tok-${index}-${'t'.repeat(16)}` });
  expect([issued.size, gate.mentionsToken({ value: `tok-0-${'t'.repeat(16)}` }), gate.mentionsToken({ value: `tok-${ISSUED_TOKEN_MEMORY_LIMIT}-${'t'.repeat(16)}` })])
    .toEqual([ISSUED_TOKEN_MEMORY_LIMIT, false, true]);
});

test('a token obtained again counts as newest, so a token in active use is not the one that falls out', async () => {
  const gate = openCapabilityGate({ isLive: () => true, issued: new Set() });
  const live = `live-${'t'.repeat(16)}`;
  gate.noteToken({ token: live });
  for (let index = 1; index < ISSUED_TOKEN_MEMORY_LIMIT; index += 1) gate.noteToken({ token: `tok-${index}-${'t'.repeat(16)}` });
  gate.noteToken({ token: live });
  gate.noteToken({ token: `tok-last-${'t'.repeat(16)}` });
  expect(gate.mentionsToken({ value: live })).toBe(true);
});

test('an error whose message or cause contains an issued token is replaced; a clean error passes through', async () => {
  await expect(runWith({ invoke: async ({ capabilities }) => { throw new Error(`bad ${await capabilities.connections.getAccessToken({ connectionRef: 'c1' })}`); } }))
    .rejects.toThrow(WITHHELD_ERROR_MESSAGE);
  await expect(runWith({ invoke: async ({ capabilities }) => { throw new Error('outer', { cause: new Error(await capabilities.connections.getAccessToken({ connectionRef: 'c1' })) }); } }))
    .rejects.toThrow(WITHHELD_ERROR_MESSAGE);
  const clean = Object.assign(new Error('Rate limited; retry later.'), { code: 'rate-limited', retryable: true });
  await expect(runWith({ invoke: async ({ capabilities }) => { await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); throw clean; } })).rejects.toBe(clean);
  expect(FAKE_TOKEN.length).toBeGreaterThan(20);
});

test('a destructive tool always requires confirmation, even under direct host approval', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'fixture-tools', files: {
      [TOOLS_FILENAME]: toolsFile([declare({ name: 'wipe', effect: 'destructive', module: 'tools/wipe.mjs' })]),
      'tools/wipe.mjs': "export default { invoke: () => 'wiped', describeAffectedResources: ({ input }) => ['record ' + input.ref] };\n",
    } });
    const harness = createHarness();
    expect(await harness.refresh()).toEqual([]);
    expect(harness.tools.list({}).find(tool => tool.id === 'p_fixture_tools__wipe')?.requiresConfirmation).toBe(true);
    expect(await harness.projection.describeAffectedResources({ toolId: 'p_fixture_tools__wipe', input: { ref: 'r1' } })).toEqual({ effect: 'destructive', resources: ['record r1'] });
  });
});

test('an invalid affected-resources answer blocks confirmation', async () => {
  const { projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', { effect: 'write' }, { invoke: () => 'ok', describeAffectedResources: () => [''] })], refusals: [] });
  await expect(projection.describeAffectedResources({ toolId: 'p_p__look', input: { ref: 'x' } }))
    .rejects.toThrow("Plugin tool 'p_p__look' returned an invalid affected-resources list; the call cannot be confirmed.");
});

/** A write tool whose module keeps the token from its last call in module scope, as M5 assumes a plugin may. */
async function disclosureAfterACall(describe: (remembered: string) => unknown) {
  const { registry, projection } = projectionFor();
  let remembered = '';
  projection.sync({ loaded: [loaded('p', { effect: 'write' }, {
    invoke: async ({ capabilities }) => { remembered = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return 'ok'; },
    describeAffectedResources: () => describe(remembered),
  })], refusals: [] });
  const snapshot = registry.list({})[0]!;
  await snapshot.tools[0]!.handler({ pluginId: 'p', sdk: snapshot.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'c1' } });
  return projection.describeAffectedResources({ toolId: 'p_p__look', input: { ref: 'x' } });
}

test('an affected-resources answer that mentions a token the plugin obtained is refused', async () => {
  await expect(disclosureAfterACall(remembered => [`sheet ${remembered}`]))
    .rejects.toThrow("Plugin tool 'p_p__look' returned an invalid affected-resources list; the call cannot be confirmed.");
});

test('an affected-resources hook error that mentions a token the plugin obtained is withheld', async () => {
  await expect(disclosureAfterACall(remembered => { throw new Error(`cannot describe ${remembered}`); })).rejects.toThrow(WITHHELD_ERROR_MESSAGE);
});

test('a clean affected-resources hook error passes through as the same error', async () => {
  const clean = new Error('sheet not found');
  await expect(disclosureAfterACall(() => { throw clean; })).rejects.toBe(clean);
});

test('a clean affected-resources answer after a call is disclosed', async () => {
  expect(await disclosureAfterACall(() => ['sheet Leads'])).toEqual({ effect: 'write', resources: ['sheet Leads'] });
});

test('disabling the plugin removes its tools, refuses authorized and direct calls and revokes retained capabilities', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'fixture-tools', files: {
      [TOOLS_FILENAME]: toolsFile([declare()]),
      'tools/look.mjs': 'export default { invoke: ({ input, capabilities }) => { globalThis.__keptCapabilities = capabilities; return { read: input.ref }; } };\n',
    } });
    const harness = createHarness();
    await harness.refresh();
    expect(await harness.invoke('p_fixture_tools__look', { ref: 'r1' })).toEqual({ read: 'r1' });
    const kept = (globalThis as { __keptCapabilities?: AgentPluginToolCapabilities }).__keptCapabilities!;
    delete (globalThis as { __keptCapabilities?: unknown }).__keptCapabilities;
    const pending = await harness.authorize('p_fixture_tools__look', { ref: 'r2' });
    const oldGeneration = harness.contributions.list({})[0]!;

    await setAgentPluginActivation({ workspaceRoot, pluginId: 'fixture-tools', enabled: false, actor: 'test' }, { origin: 'bundled' });
    expect(await harness.refresh()).toEqual([]);

    expect(harness.tools.has({ toolId: 'p_fixture_tools__look' })).toBe(false);
    await expect(pending()).rejects.toThrow('Plugin tool is disabled or was reloaded.');
    await expect(oldGeneration.tools[0]!.handler({ pluginId: 'fixture-tools', sdk: oldGeneration.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'r3' } }))
      .rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.connections.getAccessToken({ connectionRef: 'c1' })).rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.http.fetch({ url: 'https://api.example.test/' })).rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.limiter.check({ key: 'k' })).rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.artifacts!.write({ name: 'a.csv', mediaType: 'text/csv', content: 'a' })).rejects.toThrow(REVOKED_MESSAGE);
    expect(harness.log.tokenRequests).toEqual([]);
  });
});

test('a host without an artifact store leaves artifacts absent, not a wrapper that throws', () => {
  const { artifacts: _omitted, ...host } = fakeCapabilities({ tokenRequests: [], requests: [] });
  const { capabilities } = openCapabilitySession({ capabilities: host, isLive: () => true, issued: createIssuedTokenMemories().forPlugin({ pluginId: 'acme-office' }) });
  expect(Object.hasOwn(capabilities, 'artifacts')).toBe(false);
  expect(capabilities.artifacts).toBeUndefined();
});

