import { installLegacyRevision } from '../fixtures/install-legacy-revision.js';
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { forceRemove } from "../fixtures/force-remove.js";
import { setAgentPluginActivation } from "../test-support.js";

import { normalizeBundledDigests, preferBundledAgentPluginDigests, readBundledAgentPluginDigests, recordBundledAgentPluginDigests } from "../test-support.js";
import { BUNDLED_DIGESTS_FILENAME } from "../../bundled-digests.js";
import { installAgentPlugin } from "../test-support.js";
import { type AgentPluginArchiveEntry, type AgentPluginArchiveReaderPort } from "../../install.js";
import { resolveAgentPluginLayout } from "../test-support.js";

import { resolveAgentPluginRefs } from "../test-support.js";

import { loadFixturePluginSources as loadInstalledAgentPluginToolSources } from "../test-support.js";

/**
 * @file `bundled-digests.ts` — the ledger that lets a bundled plugin's UPGRADE resolve to the digest
 * the running build published, instead of being refused as ambiguous.
 *
 * The cases that matter most here are the ones where the ledger must NOT decide anything. Its whole
 * justification is that it replaces a guess with the build's own recorded answer; a ledger that
 * narrowed an id it has no authority over would be exactly the "silently picking one" failure mode
 * `resolve-agent-plugin-refs.ts`'s header rules out. So: no entry, an entry naming a digest that is
 * not installed, and an unreadable file all have to leave the existing ambiguity refusal standing,
 * and each is asserted below against the REAL surfaces rather than only against the pure selector.
 */

const WORKSPACE_ID = "55555555-5555-4555-8555-555555555555";
const DIGEST_A = "a".repeat(64);
const DIGEST_B = "b".repeat(64);
const DIGEST_C = "c".repeat(64);

function reader(entries: readonly AgentPluginArchiveEntry[]): AgentPluginArchiveReaderPort {
  return {
    async *entries() {
      yield* entries;
    },
  };
}

function fileEntry(entryPath: string, content: string): AgentPluginArchiveEntry {
  const bytes = Buffer.from(content, "utf8");
  return {
    kind: "file",
    entryPath,
    declaredSize: bytes.byteLength,
    executable: false,
    async *openReadStream() {
      yield bytes;
    },
  };
}

/** A temp instance root exported through `PLUGIN_ROOT`, because
 *  `loadInstalledAgentPluginToolSources` resolves its own layout from the environment rather than
 *  taking one. */
async function withWorkspace<T>(fn: (context: { readonly cwd: string; readonly workspaceRoot: string }) => Promise<T>): Promise<T> {
  const dir = await mkdtemp(path.join(tmpdir(), "host-bundled-digests-"));
  const previous = process.env.PLUGIN_ROOT;
  process.env.PLUGIN_ROOT = dir;
  try {
    return await fn({ cwd: dir, workspaceRoot: resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID }).root });
  } finally {
    if (previous === undefined) delete process.env.PLUGIN_ROOT;
    else process.env.PLUGIN_ROOT = previous;
    await forceRemove(dir);
  }
}

/** Installs one real package through the production pipeline, keyed to a unique archive so a second
 *  call for the same `pluginId` produces a genuinely different digest. */
async function installRealPackage(pluginId: string, skillMarkdown: string, archiveSeed: string) {
  const archive = new Uint8Array(Buffer.from(archiveSeed));
  // These ledger tests deliberately reproduce the retained digests of pre-pruning installs.
  return installLegacyRevision({ packagesDir: resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID }).pluginPackagesDir({ pluginId }), install: () => installAgentPlugin({
    archive,
    expectedSha256: createHash("sha256").update(archive).digest("hex"),
    archiveReader: reader([
      fileEntry("plugin.json", JSON.stringify({ $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json", name: pluginId, version: "1.0.0" })),
      fileEntry(`skills/${pluginId}/SKILL.md`, skillMarkdown),
    ]),
    layout: resolveAgentPluginLayout(),
    workspaceId: WORKSPACE_ID,
  }) });
}

test("normalizeBundledDigests keeps only well-formed entries and rejects a foreign envelope", () => {
  assert.deepEqual([...normalizeBundledDigests({ schemaVersion: 1, plugins: { github: { archiveDigest: DIGEST_A } } })], [["github", DIGEST_A]]);
  assert.deepEqual([...normalizeBundledDigests({ schemaVersion: 2, plugins: { github: { archiveDigest: DIGEST_A } } })], []);
  assert.deepEqual([...normalizeBundledDigests({ plugins: { github: { archiveDigest: DIGEST_A } } })], []);
  assert.deepEqual([...normalizeBundledDigests("not a document")], []);
  assert.deepEqual(
    [...normalizeBundledDigests({ schemaVersion: 1, plugins: { github: { archiveDigest: "not-a-digest" }, supabase: { archiveDigest: DIGEST_B } } })],
    [["supabase", DIGEST_B]],
    "one malformed entry must not discard its well-formed siblings",
  );
});

test("preferBundledAgentPluginDigests narrows ONLY an id the ledger can speak for", () => {
  const installed = [
    { pluginId: "github", archiveDigest: DIGEST_A },
    { pluginId: "github", archiveDigest: DIGEST_B },
    { pluginId: "supabase", archiveDigest: DIGEST_C },
  ];

  assert.deepEqual(preferBundledAgentPluginDigests(installed, new Map()), installed, "no ledger: every candidate survives, so the caller still refuses");
  assert.deepEqual(
    preferBundledAgentPluginDigests(installed, new Map([["github", DIGEST_C]])),
    installed,
    "a ledger naming a digest that is NOT one of the candidates decides nothing",
  );
  assert.deepEqual(
    preferBundledAgentPluginDigests(installed, new Map([["supabase", DIGEST_C]])),
    installed,
    "a single-digest id is already unambiguous and is never filtered",
  );
  assert.deepEqual(preferBundledAgentPluginDigests(installed, new Map([["github", DIGEST_B]])), [
    { pluginId: "github", archiveDigest: DIGEST_B },
    { pluginId: "supabase", archiveDigest: DIGEST_C },
  ]);
});

test("recordBundledAgentPluginDigests merges over earlier boots and refuses a self-contradictory build", async () => {
  const dir = await mkdtemp(path.join(tmpdir(), "host-bundled-digests-record-"));
  try {
    await recordBundledAgentPluginDigests({
      workspaceRoot: dir,
      seeded: [
        { pluginId: "github", archiveDigest: DIGEST_A },
        { pluginId: "supabase", archiveDigest: DIGEST_B },
      ],
    });

    // A later boot that seeded only github — supabase failed, or was dropped from this build's
    // source root — must not cost supabase the entry the earlier boot recorded.
    await recordBundledAgentPluginDigests({ workspaceRoot: dir, seeded: [{ pluginId: "github", archiveDigest: DIGEST_C }] });
    assert.deepEqual(
      [...(await readBundledAgentPluginDigests(dir))].sort(),
      [
        ["github", DIGEST_C],
        ["supabase", DIGEST_B],
      ].sort(),
    );

    // Two bundled source directories declaring the same manifest name under different content: the
    // BUILD is ambiguous, so there is nothing authoritative to record and the prior entry goes too.
    await recordBundledAgentPluginDigests({
      workspaceRoot: dir,
      seeded: [
        { pluginId: "github", archiveDigest: DIGEST_A },
        { pluginId: "github", archiveDigest: DIGEST_B },
      ],
    });
    assert.deepEqual([...(await readBundledAgentPluginDigests(dir))], [["supabase", DIGEST_B]]);

    const onDisk = JSON.parse(await readFile(path.join(dir, BUNDLED_DIGESTS_FILENAME), "utf8"));
    assert.equal(onDisk.schemaVersion, 1, "the file must stay a schemaVersion 1 document");
  } finally {
    await forceRemove(dir);
  }
});

test("a boot that seeded nothing writes no ledger at all", async () => {
  const dir = await mkdtemp(path.join(tmpdir(), "host-bundled-digests-empty-"));
  try {
    await recordBundledAgentPluginDigests({ workspaceRoot: path.join(dir, "never-created"), seeded: [] });
    assert.deepEqual([...(await readBundledAgentPluginDigests(path.join(dir, "never-created")))], []);
  } finally {
    await forceRemove(dir);
  }
});

test("an OPERATOR-installed plugin under two digests is still refused — the ledger has no say over it", async () => {
  await withWorkspace(async () => {
    const first = await installRealPackage("ui-ux-design", "# Variant A\n", "operator-archive-a");
    const second = await installRealPackage("ui-ux-design", "# Variant B\n", "operator-archive-b");
    const sorted = [first.archiveDigest, second.archiveDigest].sort();

    const layout = resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID });
    assert.deepEqual(await resolveAgentPluginRefs(["ui-ux-design"], layout), {
      ok: false,
      reason: `Agent Plugin 'ui-ux-design' matches 2 installed packages (digests: ${sorted.join(", ")}) — refusing to guess which one to use`,
    });
    assert.deepEqual(
      (await loadInstalledAgentPluginToolSources({ workspaceId: WORKSPACE_ID })).filter((source) => source.pluginId === "ui-ux-design"),
      [],
      "an ambiguous operator install must still be excluded from tool registration",
    );
  });
});

test("a ledger naming a digest this workspace does not have leaves the ambiguity refusal standing", async () => {
  await withWorkspace(async ({ workspaceRoot }) => {
    const first = await installRealPackage("ui-ux-design", "# Variant A\n", "absent-ledger-a");
    const second = await installRealPackage("ui-ux-design", "# Variant B\n", "absent-ledger-b");
    const sorted = [first.archiveDigest, second.archiveDigest].sort();

    await recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId: "ui-ux-design", archiveDigest: DIGEST_A }] });

    const layout = resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID });
    assert.deepEqual(await resolveAgentPluginRefs(["ui-ux-design"], layout), {
      ok: false,
      reason: `Agent Plugin 'ui-ux-design' matches 2 installed packages (digests: ${sorted.join(", ")}) — refusing to guess which one to use`,
    });
  });
});

test("an UNREADABLE ledger reads as empty, so the ambiguity refusal still fires", async () => {
  await withWorkspace(async ({ workspaceRoot }) => {
    const first = await installRealPackage("ui-ux-design", "# Variant A\n", "corrupt-ledger-a");
    const second = await installRealPackage("ui-ux-design", "# Variant B\n", "corrupt-ledger-b");
    const sorted = [first.archiveDigest, second.archiveDigest].sort();

    await writeFile(path.join(workspaceRoot, BUNDLED_DIGESTS_FILENAME), "{ this is not json", "utf8");
    assert.deepEqual([...(await readBundledAgentPluginDigests(workspaceRoot))], []);

    const layout = resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID });
    assert.deepEqual(await resolveAgentPluginRefs(["ui-ux-design"], layout), {
      ok: false,
      reason: `Agent Plugin 'ui-ux-design' matches 2 installed packages (digests: ${sorted.join(", ")}) — refusing to guess which one to use`,
    });
  });
});

test("a DISABLED plugin under two digests stays harmless — the activation gate answers first", async () => {
  await withWorkspace(async ({ workspaceRoot }) => {
    await installRealPackage("ui-ux-design", "# Variant A\n", "disabled-ambiguous-a");
    await installRealPackage("ui-ux-design", "# Variant B\n", "disabled-ambiguous-b");
    await setAgentPluginActivation({ workspaceRoot, pluginId: "ui-ux-design", enabled: false, actor: "operator:test" });

    const layout = resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID });
    const injected = await resolveAgentPluginRefs(["ui-ux-design"], layout);
    assert.ok(injected.ok === false && injected.reason.includes("is installed in this workspace but is not enabled"));
    assert.deepEqual(await loadInstalledAgentPluginToolSources({ workspaceId: WORKSPACE_ID }), []);
  });
});

test("a first-ever install resolves exactly as before, ledger or no ledger", async () => {
  await withWorkspace(async ({ workspaceRoot }) => {
    const only = await installRealPackage("ui-ux-design", "# Only one\n\nUse an 8px spacing grid.\n", "first-install-a");

    const layout = resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID });
    const withoutLedger = await resolveAgentPluginRefs(["ui-ux-design"], layout);
    assert.ok(withoutLedger.ok && withoutLedger.promptPrefix.includes("Use an 8px spacing grid."));

    await recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId: "ui-ux-design", archiveDigest: only.archiveDigest }] });
    const withLedger = await resolveAgentPluginRefs(["ui-ux-design"], layout);
    assert.deepEqual(withLedger, withoutLedger, "a ledger for an already-unambiguous id must change nothing at all");
  });
});

test("the bundled ledger selects one upgrade's content on both real resolution surfaces", async () => {
  await withWorkspace(async ({ workspaceRoot }) => {
    const oldMarkdown = "# Old bundled guidance\n\nUse the obsolete variant.\n";
    const newMarkdown = "# Current bundled guidance\n\nUse the published variant.\n";
    const old = await installRealPackage("ui-ux-design", oldMarkdown, "bundled-upgrade-old");
    const published = await installRealPackage("ui-ux-design", newMarkdown, "bundled-upgrade-published");
    assert.notEqual(old.archiveDigest, published.archiveDigest);
    await recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId: "ui-ux-design", archiveDigest: published.archiveDigest }] });

    const resolved = await resolveAgentPluginRefs(["ui-ux-design"], resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID }));
    assert.equal(resolved.ok, true, JSON.stringify(resolved));
    assert.ok(resolved.promptPrefix.includes(newMarkdown));
    assert.equal(resolved.promptPrefix.includes(oldMarkdown), false);

    const sources = (await loadInstalledAgentPluginToolSources({ workspaceId: WORKSPACE_ID })).filter((source) => source.pluginId === "ui-ux-design");
    assert.equal(sources.length, 1);
    assert.equal(sources[0]?.archiveDigest, published.archiveDigest);
    assert.deepEqual(sources[0]?.skills.map((skill) => skill.markdown), [newMarkdown]);
  });
});

src/admin-surfaces/__tests__/delivery-bi.source:
/**
 * @file Security pins for the admin-surface `deliveryBindings` port: a surface manages form-delivery
 * bindings only for the delivery adapters it declared and only through its declared connections; a
 * binding's config is bounded plain JSON that never carries a token the plugin obtained (on the way in
 * and on the way out); another adapter's binding can be neither listed, overwritten nor removed; every
 * call needs a signed-in admin; disabling the plugin revokes the port. The host is the shared typed
 * fake, which deliberately lists every binding in the workspace, so the filtering proven here is Jini's.
 */
import { describe, expect, test } from 'vitest';
import { REVOKED_MESSAGE, createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { FAKE_TOKEN, WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import { createAdminSurfaceActionDispatcher, createAdminSurfaceHandlerHost, parseAdminSurfacesFile, type AdminSurfaceCapabilityDeclarations, type AdminSurfaceDescriptor, type AdminSurfaceHandlerModule } from '../index.js';
import type { AdminSurfaceDeliveryBinding } from '../delivery-bindings.js';
import { ADMIN_SURFACE_STATE_LIMITS, openAdminSurfaceCapabilitySession, STATE_CREDENTIAL_MESSAGE } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const PLUGIN = 'acme-office';
const DECLARED: AdminSurfaceCapabilityDeclarations = { connections: [{ id: 'account', startParams: [], callbackFields: [] }], deliveryAdapters: ['acme-rows'] };
const OURS: AdminSurfaceDeliveryBinding = { bindingId: 'ours-1', adapterId: 'acme-rows', connectionId: 'account', enabled: true, allForms: true, config: { tab: 7 } };
const FOREIGN: AdminSurfaceDeliveryBinding = { bindingId: 'foreign-1', adapterId: 'other-adapter', connectionId: 'account', enabled: true, formIds: ['contact'], config: { list: 'x' } };
const DRAFT = { adapterId: 'acme-rows', connectionId: 'account', enabled: true, formIds: ['contact'], config: { tab: 1 } } as const;
const NO_FORMS = 'A delivery binding must name its forms: formIds (a list; [] for none) or allForms: true for every current and future form, not both.';
const NO_ACTOR = 'Delivery settings need a signed-in admin. Open the surface from an authenticated admin page and retry.';
const NOT_OURS = (id: string) => `No delivery binding '${id}' belongs to this surface's delivery adapters; list the bindings and retry.`;

function open(optional: { readonly actorId?: string | null; readonly live?: () => boolean; readonly issued?: Set<string> } = {}) {
  const fake = createFakeSurfaceHost({ bindings: [OURS, FOREIGN] });
  const actorId = optional.actorId === undefined ? 'admin-1' : optional.actorId;
  const session = openAdminSurfaceCapabilitySession(
    { capabilities: fake.port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: optional.live ?? (() => true), declared: DECLARED, issued: optional.issued ?? new Set() },
    actorId === null ? {} : { actorId },
  );
  return { ...fake, ...session, bindingsPort: session.capabilities.deliveryBindings! };
}

const surfaceRaw = (extra: Record<string, unknown>) => JSON.stringify({ schemaVersion: 1, surfaces: [{
  id: 'destination', title: 'Destination', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs',
  actions: [{ name: 'save', input: { type: 'object' }, result: { type: 'object', properties: { count: { type: 'integer' } } } }], ...extra,
}] });
const reasonFor = (extra: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: surfaceRaw(extra) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('the surfaces file declares which delivery adapters a surface manages', () => {
  test('deliveryAdapters without a handler module is refused', () => {
    expect(reasonFor({ handlerModule: undefined, actions: [], deliveryAdapters: ['acme-rows'] })).toBe('surfaces[0].deliveryAdapters needs a handlerModule that uses it');
  });
  test.each([
    ['not an array', 'acme-rows'],
    ['more than 8', Array.from({ length: 9 }, (_, index) => `adapter-${index}`)],
  ])('a deliveryAdapters list that is %s is refused', (_label, deliveryAdapters) => {
    expect(reasonFor({ deliveryAdapters })).toBe('surfaces[0].deliveryAdapters must be an array of at most 8');
  });
  test.each([['Acme-Rows'], ['../rows'], ['a'.repeat(65)], [7]])('a delivery adapter id %j that is not a lowercase hyphenated id is refused', (id) => {
    expect(reasonFor({ deliveryAdapters: ['acme-rows', id] })).toBe('surfaces[0].deliveryAdapters[1] must be a unique name matching ^(?=.{1,64}$)[a-z0-9]+(?:-[a-z0-9]+)*$');
  });
  test('a delivery adapter declared twice is refused', () => {
    expect(reasonFor({ deliveryAdapters: ['acme-rows', 'acme-rows'] })).toBe('surfaces[0].deliveryAdapters[1] must be a unique name matching ^(?=.{1,64}$)[a-z0-9]+(?:-[a-z0-9]+)*$');
  });
  test('declared adapters are parsed onto the descriptor', () => {
    const parsed = parseAdminSurfacesFile({ raw: surfaceRaw({ deliveryAdapters: ['acme-rows', 'a'.repeat(64)] }) });
    expect(parsed.ok && parsed.descriptors[0]!.deliveryAdapters).toStrictEqual(['acme-rows', 'a'.repeat(64)]);
  });
});

describe('the port exists only where it is declared and provided', () => {
  test('a surface that declares no delivery adapters gets no deliveryBindings port', () => {
    const session = openAdminSurfaceCapabilitySession({ capabilities: createFakeSurfaceHost().port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: () => true, declared: { connections: DECLARED.connections! }, issued: new Set() }, { actorId: 'admin-1' });
    expect(session.capabilities).not.toHaveProperty('deliveryBindings');
  });
  test('a host that provides no deliveryBindings port leaves it absent', () => {
    const session = openAdminSurfaceCapabilitySession({ capabilities: createFakeSurfaceHost({ deliveryBindings: false }).port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued: new Set() }, { actorId: 'admin-1' });
    expect(session.capabilities).not.toHaveProperty('deliveryBindings');
  });
});

describe('save: only declared adapters and connections, bounded token-free config', () => {
  test('an undeclared adapter is refused before the host sees it', async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...DRAFT, adapterId: 'other-adapter' }))
      .rejects.toThrow("This admin surface does not declare delivery adapter 'other-adapter', so its handlers cannot manage its bindings. Declare it in the surface's deliveryAdapters.");
    expect(session.log.calls).toEqual([]);
  });
  test('a connection the surface did not declare is refused before the host sees it', async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...DRAFT, connectionId: 'other-plugins-account' }))
      .rejects.toThrow("Delivery bindings may only use this surface's declared connections; 'other-plugins-account' is not one of them.");
    expect(session.log.calls).toEqual([]);
  });
  test('a config one byte over the limit is refused and nothing is saved', async () => {
    const session = open();
    const config = { pad: 'x'.repeat(ADMIN_SURFACE_STATE_LIMITS.maxValueBytes - '{"pad":""}'.length + 1) };
    await expect(session.bindingsPort.save({ ...DRAFT, config })).rejects.toThrow('A settings value may be at most 16384 bytes of JSON.');
    expect(session.log.calls).toEqual([]);
  });
  test('a config mentioning a token the plugin obtained is refused and nothing is saved', async () => {
    const session = open();
    const token = await session.capabilities.connections.getAccessToken({ connectionId: 'account' });
    await expect(session.bindingsPort.save({ ...DRAFT, config: { header: `Bearer ${token}` } })).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
    expect(session.log.calls).toEqual([]);
  });
  test('a config mentioning a token an earlier call (or a tool) obtained is refused', async () => {
    const session = open({ issued: new Set([FAKE_TOKEN]) });
    await expect(session.bindingsPort.save({ ...DRAFT, config: { nested: [{ value: FAKE_TOKEN }] } })).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
    expect(session.bindings.get('binding-3')).toBeUndefined();
  });
  test("another adapter's binding cannot be overwritten through its binding id", async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...DRAFT, bindingId: 'foreign-1' })).rejects.toThrow(NOT_OURS('foreign-1'));
    expect(session.bindings.get('foreign-1')).toStrictEqual(FOREIGN);
    expect(session.log.calls).toEqual([`${PLUGIN}:bindings.list:{}`]);
  });
});

describe('list and remove never reach another adapter\'s bindings', () => {
  test('list returns only the declared adapters\' bindings, even when the host returns more', async () => {
    await expect(open().bindingsPort.list()).resolves.toStrictEqual([OURS]);
  });
  test('list withholds the bindings when one mentions a token the plugin obtained', async () => {
    const session = open({ issued: new Set([FAKE_TOKEN]) });
    session.bindings.set('ours-2', { ...OURS, bindingId: 'ours-2', config: { leaked: FAKE_TOKEN } });
    await expect(session.bindingsPort.list()).rejects.toThrow('A delivery binding held a connection credential, so it was withheld. Remove it and save it again.');
  });
  test("removing another adapter's binding is refused and it stays", async () => {
    const session = open();
    await expect(session.bindingsPort.remove({ bindingId: 'foreign-1' })).rejects.toThrow(NOT_OURS('foreign-1'));
    expect(session.bindings.get('foreign-1')).toStrictEqual(FOREIGN);
    expect(session.log.calls).not.toContain(`${PLUGIN}:bindings.remove:{"bindingId":"foreign-1"}`);
  });
});

describe('which forms a binding delivers is always stated (never an implicit "every form")', () => {
  const { formIds: _formIds, ...noForms } = DRAFT;
  test.each([
    ['neither formIds nor allForms', noForms],
    ['allForms: false', { ...noForms, allForms: false }],
    ['allForms as a string', { ...noForms, allForms: 'true' }],
    ['both formIds and allForms', { ...DRAFT, allForms: true }],
  ])('a draft with %s is refused before the host sees it', async (_label, draft) => {
    const session = open();
    // Malformed on purpose: a plugin is JavaScript and may send any of these.
    await expect(session.bindingsPort.save(draft as unknown as Parameters<typeof session.bindingsPort.save>[0])).rejects.toThrow(NO_FORMS);
    expect(session.log.calls).toEqual([]);
  });
  test('allForms: true reaches the host as stated, without a formIds key', async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...noForms, allForms: true })).resolves.toMatchObject({ allForms: true });
    expect(session.log.calls.at(-1)).toBe('acme-office:bindings.save:{"adapterId":"acme-rows","connectionId":"account","enabled":true,"allForms":true,"config":{"tab":1}}');
  });
  test('a binding the host lists without stating its forms is refused, never read as every form', async () => {
    const session = open();
    const { allForms: _allForms, ...unstated } = OURS as AdminSurfaceDeliveryBinding & { allForms: true };
    // Malformed on purpose: a host that still stores "absent = every form" must map it to allForms: true.
    session.bindings.set('ours-1', unstated as unknown as AdminSurfaceDeliveryBinding);
    await expect(session.bindingsPort.list()).rejects.toThrow("The host listed delivery binding 'ours-1' without formIds or allForms; fix the host's binding store.");
  });
});

describe('a signed-in admin and a live plugin are required', () => {
  test.each([
    ['list', (s: ReturnType<typeof open>) => s.bindingsPort.list()],
    ['save', (s: ReturnType<typeof open>) => s.bindingsPort.save(DRAFT)],
    ['remove', (s: ReturnType<typeof open>) => s.bindingsPort.remove({ bindingId: 'ours-1' })],
  ])('%s without a signed-in admin is refused before the host sees it', async (_name, call) => {
    const session = open({ actorId: null });
    await expect(call(session)).rejects.toThrow(NO_ACTOR);
    expect(session.log.calls).toEqual([]);
  });

  test.each([
    ['list', (s: ReturnType<typeof open>) => s.bindingsPort.list()],
    ['save', (s: ReturnType<typeof open>) => s.bindingsPort.save(DRAFT)],
    ['remove', (s: ReturnType<typeof open>) => s.bindingsPort.remove({ bindingId: 'ours-1' })],
  ])('%s on a revoked session is refused before the host sees it', async (_name, call) => {
    const session = open({ live: () => false });
    await expect(call(session)).rejects.toThrow(REVOKED_MESSAGE);
    expect(session.log.calls).toEqual([]);
  });

  test('a port a handler module kept is revoked once the plugin is disabled', async () => {
    const parsed = parseAdminSurfacesFile({ raw: surfaceRaw({ connections: [{ id: 'account' }], deliveryAdapters: ['acme-rows'] }) });
    const descriptor = (parsed.ok ? parsed.descriptors[0] : undefined) as AdminSurfaceDescriptor & { handlerModule: string };
    let kept: Parameters<AdminSurfaceHandlerModule['actions'][string]>[0]['capabilities'] | undefined;
    const fake = createFakeSurfaceHost({ bindings: [OURS] });
    const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: fake.port });
    host.sync({ loaded: [{ pluginId: PLUGIN, descriptor, module: { actions: { save: async ({ capabilities }) => { kept = capabilities; return { count: (await capabilities.deliveryBindings!.list()).length }; } } } }], refusals: [] });
    const context = { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'destination' };
    await expect(createAdminSurfaceActionDispatcher({ descriptor, handlers: host.handlersFor({ pluginId: PLUGIN, surfaceId: 'destination' }) }).dispatch({ action: 'save', payload: {}, context }))
      .resolves.toStrictEqual({ ok: true, result: { count: 1 } });
    host.sync({ loaded: [], refusals: [] });
    for (const call of [kept!.deliveryBindings!.list(), kept!.deliveryBindings!.save(DRAFT), kept!.deliveryBindings!.remove({ bindingId: 'ours-1' })]) await expect(call).rejects.toThrow(REVOKED_MESSAGE);
    expect(fake.bindings.get('ours-1')).toStrictEqual(OURS);
  });
});

src/lifecycle/__tests__/unit/lifecycle-f.source:
import { afterAll, beforeAll, describe, expect, test } from 'vitest';
import { createHash } from 'node:crypto';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {
  AgentPluginNotInstalledError, PackagePathViolation, createAgentPluginLayout, createAgentPluginLifecycle,
  type AgentPluginArchiveReaderPort, type InstalledAgentPlugin,
} from '../../index.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

/**
 * @file Contract tests for `createAgentPluginLifecycle`'s object-API facade: each adapter maps its
 * `{ ...input }` object onto the module function's positional arguments. Every assertion is a real
 * outcome against one installed package in a temp layout, so a swapped or dropped argument fails.
 */

const workspaceId = 'facade-ws';
const pluginId = 'facade-plugin';
const files: Record<string, string> = {
  'plugin.json': JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: pluginId, description: 'Charts and dashboards' }),
  [`skills/${pluginId}/SKILL.md`]: '# Facade skill\nBody',
  'mcp.json': JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json', mcpServers: { main: { type: 'stdio', command: './server.js' } } }),
  'contrib.json': JSON.stringify(['alpha']),
  'module.mjs': 'export default { greeting: "hello from module" };',
};
const archive = Buffer.from('facade-archive');
const digest = createHash('sha256').update(archive).digest('hex');
const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
  for (const [entryPath, text] of Object.entries(files)) yield { kind: 'file', entryPath, async *openReadStream() { yield Buffer.from(text); } };
} };

let root: string;
let layout: ReturnType<typeof createAgentPluginLayout>;
let api: ReturnType<typeof createAgentPluginLifecycle>;
let installed: InstalledAgentPlugin;
let workspaceRoot: string;
beforeAll(async () => {
  root = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'lifecycle-facade-')));
  layout = createAgentPluginLayout({ root });
  api = createAgentPluginLifecycle({ ...ports, layout }, { onEvent: () => undefined });
  installed = await api.installAgentPlugin({ layout, workspaceId, archive, archiveReader, expectedSha256: digest });
  workspaceRoot = layout.forWorkspace({ workspaceId }).root;
});
afterAll(async () => { await forceRemove(root); });

describe('construction validates the host context', () => {
  test.each([
    [{ productName: '  ' }], [{ extensionNamespace: '' }], [{ bundledArchiveMagic: '' }],
  ])('refuses a blank required identity %j', override => {
    expect(() => createAgentPluginLifecycle({ ...ports, ...override })).toThrow('productName, extensionNamespace and bundledArchiveMagic are required');
  });
  test('refuses an unknown delivery mode', () => {
    expect(() => createAgentPluginLifecycle({ ...ports, deliveryMode: 'email' as 'inject' })).toThrow('Invalid deliveryMode');
  });
});

describe('positional adapters reach the installed package', () => {
  test('package paths and archive limits', async () => {
    expect(api.normalizePackageEntryPath({ rawEntryPath: 'a\\b/../c.md' })).toBe('a/c.md');
    expect(await api.assertContainedOnDisk({ packageRoot: installed.packageRoot, entryPath: 'plugin.json' })).toBe(path.join(installed.packageRoot, 'plugin.json'));
    await expect(api.assertContainedOnDisk({ packageRoot: installed.packageRoot, entryPath: '../x' })).rejects.toBeInstanceOf(PackagePathViolation);
    expect(api.maxAgentPluginInstallArchiveBytes({})).toBeGreaterThan(0);
  });

  test('capability projection reads skill markdown and MCP servers', async () => {
    expect(await api.readInstalledSkillMarkdown({ packageRoot: installed.packageRoot, skillPath: `skills/${pluginId}/SKILL.md` })).toBe('# Facade skill\nBody');
    expect(await api.readInstalledMcpServerIds({ packageRoot: installed.packageRoot })).toEqual(['main']);
    expect(Object.keys(await api.readInstalledMcpServers({ packageRoot: installed.packageRoot }))).toEqual(['main']);
    expect(api.classifyAgentPluginMcpServerTrust({ server: { type: 'stdio' } })).toBe('requires-confirmation');
    expect(api.classifyAgentPluginMcpServerTrust({ server: { type: 'streamable-http' } })).toBe('auto-admit');
  });

  test('installed listing, digest presence and re-indexing agree on the one package', async () => {
    const workspace = layout.forWorkspace({ workspaceId });
    expect((await api.listInstalledPlugins({ workspaceRoot })).map(plugin => plugin.pluginId)).toEqual([pluginId]);
    expect(await api.isInstalledDigestPresent({ packagesDir: workspace.pluginPackagesDir({ pluginId }), archiveDigest: digest })).toBe(true);
    expect(await api.isInstalledDigestPresent({ packagesDir: workspace.pluginPackagesDir({ pluginId }), archiveDigest: 'f'.repeat(64) })).toBe(false);
    const indexed = await api.indexInstalledRoot({ packageRoot: installed.packageRoot, archiveDigest: digest });
    expect(indexed).toMatchObject({ pluginId, archiveDigest: digest, packageRoot: installed.packageRoot });
  });

  test('search ranks the installed candidate by query and honours the limit', () => {
    const candidates = [{ pluginId, description: 'Charts and dashboards', keywords: [], enabled: true, skills: [], mcpServerIds: [] }, { pluginId: 'other', description: 'Email', keywords: [], enabled: true, skills: [], mcpServerIds: [] }];
    expect(api.rankInstalledAgentPlugins({ query: 'dashboards', candidates, limit: 5 }).map(match => match.pluginId)).toEqual([pluginId]);
    expect(api.rankInstalledAgentPlugins({ query: '', candidates, limit: 5 }, { automatic: true })).toEqual([]);
  });

  test('activation adapters read, resolve and normalize the activation file', async () => {
    await api.assertAgentPluginActivationsWritable({ workspaceRoot });
    expect(await api.setAgentPluginEnabled({ workspaceId, pluginId, enabled: false, actor: 'admin@example' })).toEqual({ pluginId, enabled: false });
    const activations = await api.readAgentPluginActivations({ workspaceRoot });
    expect(activations.plugins[pluginId]).toMatchObject({ enabled: false, updatedBy: 'admin@example' });
    expect(api.isAgentPluginActive({ activations, pluginId })).toBe(false);
    expect((await api.resolveAgentPluginActivation({ workspaceRoot, pluginId })).verdict).toBe('inactive');
    expect(await api.isAgentPluginRecordedAsBundled({ workspaceRoot, pluginId })).toBe(false);
    expect(api.normalizeActivations({ value: activations })).toEqual(activations);
    expect(await api.setAgentPluginEnabled({ workspaceId, pluginId, enabled: true, actor: 'admin@example' })).toEqual({ pluginId, enabled: true });
  });

  test('enabling a plugin that is not installed is a typed refusal that writes nothing', async () => {
    const before = await api.readAgentPluginActivations({ workspaceRoot });
    const refusal = api.setAgentPluginEnabled({ workspaceId, pluginId: 'ghost', enabled: true, actor: 'admin@example' });
    await expect(refusal).rejects.toBeInstanceOf(AgentPluginNotInstalledError);
    await expect(refusal).rejects.toMatchObject({ name: 'AgentPluginNotInstalledError', message: "agent plugin 'ghost' is not installed in this workspace" });
    expect(await api.readAgentPluginActivations({ workspaceRoot })).toEqual(before);
  });

  test('bundled digests are recorded, read back, normalized and preferred', async () => {
    const now = () => new Date('2026-01-02T03:04:05.000Z');
    await api.recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId, archiveDigest: digest }] }, { now });
    const bundled = await api.readBundledAgentPluginDigests({ workspaceRoot });
    expect(bundled.get(pluginId)).toBe(digest);
    expect(api.normalizeBundledDigests({ value: { schemaVersion: 1, plugins: { [pluginId]: { archiveDigest: digest } } } }).get(pluginId)).toBe(digest);
    const stale = { pluginId, archiveDigest: 'e'.repeat(64) };
    const current = { pluginId, archiveDigest: digest };
    expect(api.preferBundledAgentPluginDigests({ installed: [stale, current], bundled })).toEqual([current]);
  });

  test('trusted file adapters gate on the bundled digest, then read and import contained files', async () => {
    await api.recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId, archiveDigest: digest }] });
    const verdicts = await api.findTrustedPluginPackages({ workspaceId, filename: 'contrib.json', contribution: 'widgets', requireActive: true }, { orderByPluginId: true });
    expect(verdicts).toEqual([{ trusted: { pluginId, packageRoot: installed.packageRoot } }]);
    expect(await api.findTrustedPluginPackages({ workspaceId, filename: 'not-shipped.json', contribution: 'widgets', requireActive: false })).toEqual([]);
    const plugin = { pluginId, packageRoot: installed.packageRoot };
    expect(await api.readTrustedPluginFile({ plugin, filename: 'contrib.json' })).toBe('["alpha"]');
    expect(await api.importContainedModule({ plugin, modulePath: 'module.mjs' })).toEqual({ exported: { greeting: 'hello from module' } });
    expect(await api.importContainedModule({ plugin, modulePath: '../escape.mjs' })).toBe("module path '../escape.mjs' escapes the plugin root");
  });

  test('contribution loading is wired to the trusted find/read/import owner', async () => {
    await api.recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId, archiveDigest: digest }] });
    const result = await api.loadPluginContributions({ workspaceId, definition: {
      filename: 'contrib.json', contribution: 'widgets', kind: 'executable',
      parse: ({ raw }) => ({ ok: true, descriptors: JSON.parse(raw) as string[] }),
      load: async ({ plugin, descriptor, importModule }) => {
        const loaded = await importModule({ plugin, modulePath: 'module.mjs' });
        return typeof loaded === 'string' ? loaded : { descriptor, exported: loaded.exported };
      },
    } });
    expect(result.refusals).toEqual([]);
    expect(result.items).toEqual([{ descriptor: 'alpha', exported: { greeting: 'hello from module' } }]);
  });

  test('archive fetch goes through the host outbound guard and fetch port', async () => {
    const guarded: string[] = [];
    const fetching = createAgentPluginLifecycle({ ...ports, layout,
      outboundGuard: { assertAllowed: async ({ url }) => { guarded.push(url); } },
      fetch: async () => new Response(Buffer.from('zip-bytes')) });
    const fetched = await fetching.fetchAgentPluginArchive({ url: 'https://example.invalid/p.zip' }, { maxBytes: 64 });
    expect(Buffer.from(fetched.archive).toString()).toBe('zip-bytes');
    expect(fetched.sha256).toBe(createHash('sha256').update('zip-bytes').digest('hex'));
    expect(guarded).toEqual(['https://example.invalid/p.zip']);
    expect(fetching.maxAgentPluginArchiveBytes({})).toBeGreaterThan(64);
  });

  test('activation filtering keeps only items whose plugin is active', async () => {
    await api.setAgentPluginEnabled({ workspaceId, pluginId, enabled: false, actor: 'admin@example' });
    const activations = await api.readAgentPluginActivations({ workspaceRoot });
    const items = [{ id: pluginId }, { id: 'never-recorded' }];
    expect(api.filterActiveAgentPlugins({ activations, items, pluginIdOf: ({ item }) => item.id })).toEqual([{ id: 'never-recorded' }]);
    await api.setAgentPluginEnabled({ workspaceId, pluginId, enabled: true, actor: 'admin@example' });
  });

  test('ref resolution defaults to the context delivery mode and memory is bound to the named workspace', async () => {
    const memory = api.pluginMemory({ workspaceId, pluginId });
    await memory.writeNote({ entryPath: 'facts.md', text: 'REMEMBERED' });
    const workspaceLayout = layout.forWorkspace({ workspaceId });
    const injected = await api.resolveAgentPluginRefs({ pluginRefIds: [pluginId], workspaceLayout });
    expect(injected.ok && injected.promptPrefix).toContain('REMEMBERED');
    const pointed = await api.resolveAgentPluginRefs({ pluginRefIds: [pluginId], workspaceLayout }, { deliveryMode: 'pointer' });
    expect(pointed.ok && pointed.promptPrefix).toContain(`agent_plugin_${pluginId.replace(/-/g, '_')}`);
  });

  test('a bundled source directory packs into an archive the bundled reader can read back', async () => {
    const sourceDir = path.join(root, 'bundled-source');
    await fs.mkdir(sourceDir, { recursive: true });
    await fs.writeFile(path.join(sourceDir, 'plugin.json'), files['plugin.json']!);
    const packed = await api.packAgentPluginDirectory({ sourceDir });
    const names: string[] = [];
    for await (const entry of api.createBundledSourceArchiveReader({}).entries({ archive: packed.bytes })) names.push(entry.entryPath);
    expect(names).toEqual(['plugin.json']);
  });

  test('frozen package trees can be staged, restored and removed', async () => {
    const packagesDir = path.join(root, 'stage-area');
    const tree = path.join(packagesDir, 'tree');
    await fs.mkdir(path.join(tree, 'inner'), { recursive: true });
    await fs.writeFile(path.join(tree, 'inner', 'file'), 'bytes');
    await fs.chmod(tree, 0o555);
    const staged = await api.stageForRemoval({ packagesDir, packageRoot: tree });
    await expect(fs.stat(tree)).rejects.toMatchObject({ code: 'ENOENT' });
    const cause = new Error('rolled back');
    expect(await api.restoreStagedTrees({ staged: [staged], cause })).toBe(cause);
    expect((await fs.stat(tree)).mode & 0o777).toBe(0o555);
    await api.removeFrozenPackageTree({ root: tree });
    await expect(fs.stat(tree)).rejects.toMatchObject({ code: 'ENOENT' });
  });

  test('layout migration runs against the named workspace', async () => {
    const result = await api.migratePluginLayout({ workspaceId });
    expect(result.complete).toBe(true);
    expect(JSON.parse(await fs.readFile(path.join(workspaceRoot, '.agent-plugin-layout-migrated'), 'utf8'))).toEqual({ layoutVersion: 2 });
  });
});

