import { afterEach, describe, expect, test } from 'vitest';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createAgentPluginLayout } from '../../layout.js';
import { createNodeAgentPluginEffects } from '../../node.js';
import { createPersistentStateModule } from '../../persistent-state.js';
import { createPackagePathsModule } from '../../package-paths.js';
import { createCapabilityProjectionModule } from '../../capability-projection.js';
import { createTrustedPluginFilesModule } from '../../trusted-plugin-files.js';
import { createBundledDigestsModule, BUNDLED_DIGESTS_FILENAME } from '../../bundled-digests.js';
import { createBundledSourceArchiveModule } from '../../bundled-source-archive.js';
import type { FilesystemPort } from '../../ports.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

/** @file Refusal and fallback paths of the small lifecycle modules, each through its public factory. */

const temporaries: string[] = [];
afterEach(async () => { for (const dir of temporaries.splice(0)) await forceRemove(dir); });
async function tempDir(): Promise<string> {
  const dir = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'lifecycle-edges-')));
  temporaries.push(dir);
  return dir;
}

describe('createAgentPluginLayout', () => {
  test('refuses a relative root', () => {
    expect(() => createAgentPluginLayout({ root: 'relative/root' })).toThrow('Agent plugin root must be absolute');
  });
  test('lower-cases workspace ids and refuses unsafe or over-long ones', () => {
    const layout = createAgentPluginLayout({ root: '/plugins' });
    expect(layout.forWorkspace({ workspaceId: 'Team-A' }).root).toBe('/plugins/ws/team-a');
    expect(() => layout.forWorkspace({ workspaceId: '../escape' })).toThrow("'../escape' is not a safe plugin/workspace id");
    expect(() => layout.forWorkspace({ workspaceId: 'a'.repeat(65) })).toThrow('is not a safe plugin/workspace id');
  });
  test('memory directories exist only for the learned and notes kinds', () => {
    const workspace = createAgentPluginLayout({ root: '/plugins' }).forWorkspace({ workspaceId: 'ws' });
    expect(workspace.pluginMemoryDir({ pluginId: 'acme', kind: 'notes' })).toBe('/plugins/ws/ws/acme/memory/notes');
    expect(() => workspace.pluginMemoryDir({ pluginId: 'acme', kind: 'cache' as 'notes' })).toThrow('Invalid memory kind');
  });
});

describe('createNodeAgentPluginEffects process.isAlive', () => {
  const { process: host } = createNodeAgentPluginEffects({});
  test('a non-positive or non-integer pid is never alive', () => {
    for (const pid of [0, -1, 1.5, Number.NaN]) expect(host.isAlive({ pid })).toBe(false);
  });
  test('the current process is alive and an exited child is not', async () => {
    expect(host.isAlive({ pid: process.pid })).toBe(true);
    const { spawn } = await import('node:child_process');
    const child = spawn(process.execPath, ['-e', '']);
    await new Promise(resolve => child.on('exit', resolve));
    expect(host.isAlive({ pid: child.pid! })).toBe(false);
  });
});

describe('createPersistentStateModule migration manifest policy', () => {
  test('a legacy package whose manifest the host parser refuses is quarantined, with no event port wired', async () => {
    const root = await tempDir();
    const legacy = path.join(root, 'packages', 'sha256', 'a'.repeat(64));
    await fs.mkdir(legacy, { recursive: true });
    await fs.writeFile(path.join(legacy, 'plugin.json'), JSON.stringify({ name: 'Not A Valid Name' }));
    const { onEvent: _omitted, ...withoutEvents } = ports;
    const result = await createPersistentStateModule(withoutEvents).migrate({ workspaceRoot: root });
    expect(result).toEqual({ complete: true, moved: 0 });
    const [run] = await fs.readdir(path.join(root, 'staging', 'legacy-quarantine'));
    expect(JSON.parse(await fs.readFile(path.join(root, 'staging', 'legacy-quarantine', run!, 'packages', 'sha256', 'a'.repeat(64), 'plugin.json'), 'utf8')))
      .toEqual({ name: 'Not A Valid Name' });
    await expect(fs.stat(legacy)).rejects.toMatchObject({ code: 'ENOENT' });
  });
});

describe('createPackagePathsModule', () => {
  test('when no ancestor below the root can be realpathed, the lexical path is kept under the real root', async () => {
    let calls = 0;
    const filesystem = { ...fs, realpath: (async (target: string) => {
      if (calls++ === 0) return target;
      throw Object.assign(new Error('gone'), { code: 'ENOENT' });
    }) as FilesystemPort['realpath'] } as FilesystemPort;
    const { assertContainedOnDisk } = createPackagePathsModule({ filesystem });
    expect(await assertContainedOnDisk('/pkg', 'a/b/c.md')).toBe('/pkg/a/b/c.md');
  });
});

describe('createCapabilityProjectionModule', () => {
  const capabilities = createCapabilityProjectionModule(ports);
  test('a skill path outside the package returns the recoverable refusal note, not an error', async () => {
    const root = await tempDir();
    expect(await capabilities.readInstalledSkillFile({ packageRoot: root, skillPath: '../elsewhere/SKILL.md' })).toEqual({
      text: '', files: [], note: 'File request refused: the installed skill folder is missing, unreadable, or outside the package. Valid supporting files: (none).',
    });
  });
  test('MCP servers are still read when the package has no readable plugin.json', async () => {
    const root = await tempDir();
    await fs.writeFile(path.join(root, 'mcp.json'), JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json', mcpServers: { main: { type: 'stdio', command: './server.js' } } }));
    expect(await capabilities.readInstalledMcpServerIds(root)).toEqual(['main']);
  });
});

describe('createTrustedPluginFilesModule importContainedModule', () => {
  test('returns a thrown Error message, or a thrown value as text, instead of rejecting', async () => {
    const root = await tempDir();
    await fs.writeFile(path.join(root, 'throws-error.mjs'), 'throw new Error("module refused to load");');
    await fs.writeFile(path.join(root, 'throws-value.mjs'), 'throw "plain refusal";');
    const { importContainedModule } = createTrustedPluginFilesModule(ports);
    const plugin = { pluginId: 'acme', packageRoot: root };
    expect(await importContainedModule(plugin, 'throws-error.mjs')).toBe('module refused to load');
    expect(await importContainedModule(plugin, 'throws-value.mjs')).toBe('plain refusal');
  });
  test('a filesystem fault during containment propagates rather than reading as a refusal', async () => {
    const filesystem = { ...fs, realpath: (async () => { throw Object.assign(new Error('EACCES: denied'), { code: 'EACCES' }); }) as FilesystemPort['realpath'] } as FilesystemPort;
    const { importContainedModule } = createTrustedPluginFilesModule({ ...ports, filesystem });
    await expect(importContainedModule({ pluginId: 'acme', packageRoot: '/pkg' }, 'module.mjs')).rejects.toMatchObject({ code: 'EACCES' });
  });
});

describe('createBundledDigestsModule ledger hygiene', () => {
  const digest = 'b'.repeat(64);
  test('normalization skips unsafe ids and non-object entries but keeps valid siblings', () => {
    const { normalizeBundledDigests } = createBundledDigestsModule(ports);
    const ledger = normalizeBundledDigests({ schemaVersion: 1, plugins: { 'Bad Id': { archiveDigest: digest }, scalar: 'x', good: { archiveDigest: digest } } });
    expect([...ledger]).toEqual([['good', digest]]);
  });
  test('recording ignores a seeded entry with a malformed digest', async () => {
    const root = await tempDir();
    const { recordBundledAgentPluginDigests, readBundledAgentPluginDigests } = createBundledDigestsModule(ports);
    await recordBundledAgentPluginDigests({ workspaceRoot: root, seeded: [{ pluginId: 'good', archiveDigest: digest }, { pluginId: 'bad', archiveDigest: 'not-hex' }] });
    expect([...await readBundledAgentPluginDigests(root)]).toEqual([['good', digest]]);
  });
  test('removing an id the ledger does not record reports false and leaves the file unchanged', async () => {
    const root = await tempDir();
    const { recordBundledAgentPluginDigests, removeBundledAgentPluginDigest } = createBundledDigestsModule(ports);
    await recordBundledAgentPluginDigests({ workspaceRoot: root, seeded: [{ pluginId: 'good', archiveDigest: digest }] });
    const before = await fs.readFile(path.join(root, BUNDLED_DIGESTS_FILENAME), 'utf8');
    expect(await removeBundledAgentPluginDigest({ workspaceRoot: root, pluginId: 'absent' })).toBe(false);
    expect(await fs.readFile(path.join(root, BUNDLED_DIGESTS_FILENAME), 'utf8')).toBe(before);
  });
  test('removing from a ledger of an unknown schema reports false and leaves it untouched', async () => {
    const root = await tempDir();
    await fs.writeFile(path.join(root, BUNDLED_DIGESTS_FILENAME), JSON.stringify({ schemaVersion: 2, plugins: { good: { archiveDigest: digest } } }));
    expect(await createBundledDigestsModule(ports).removeBundledAgentPluginDigest({ workspaceRoot: root, pluginId: 'good' })).toBe(false);
    expect(JSON.parse(await fs.readFile(path.join(root, BUNDLED_DIGESTS_FILENAME), 'utf8')).schemaVersion).toBe(2);
  });
  test('a failed atomic rename removes the temp file and keeps the previous ledger', async () => {
    const root = await tempDir();
    const writer = createBundledDigestsModule(ports);
    await writer.recordBundledAgentPluginDigests({ workspaceRoot: root, seeded: [{ pluginId: 'good', archiveDigest: digest }] });
    const filesystem = { ...fs, rename: (async () => { throw Object.assign(new Error('EXDEV: cross-device'), { code: 'EXDEV' }); }) as FilesystemPort['rename'] } as FilesystemPort;
    const failing = createBundledDigestsModule({ ...ports, filesystem });
    await expect(failing.removeBundledAgentPluginDigest({ workspaceRoot: root, pluginId: 'good' })).rejects.toMatchObject({ code: 'EXDEV' });
    expect(await fs.readdir(root)).toEqual([BUNDLED_DIGESTS_FILENAME]);
    expect([...await writer.readBundledAgentPluginDigests(root)]).toEqual([['good', digest]]);
  });
});

describe('createBundledSourceArchiveModule refusals', () => {
  const magic = ports.bundledArchiveMagic;
  async function readAll(bytes: Uint8Array): Promise<string[]> {
    const names: string[] = [];
    for await (const entry of createBundledSourceArchiveModule(ports).createBundledSourceArchiveReader().entries({ archive: bytes })) names.push(entry.entryPath);
    return names;
  }
  test('a directory with more files than the cap is refused before packing', async () => {
    const root = await tempDir();
    await Promise.all(Array.from({ length: 2049 }, (_, index) => fs.writeFile(path.join(root, `f${index}`), '')));
    await expect(createBundledSourceArchiveModule(ports).packAgentPluginDirectory(root)).rejects.toThrow(`has 2049 files, over the 2048-file cap`);
  });
  test('an entry header without a newline is truncated', async () => {
    await expect(readAll(Buffer.from(`${magic}F 1 1`))).rejects.toThrow('bundled agent plugin archive: truncated entry header');
  });
  test('an entry header in the wrong shape is malformed', async () => {
    await expect(readAll(Buffer.from(`${magic}X 1 1\n`))).rejects.toThrow("bundled agent plugin archive: malformed entry header 'X 1 1'");
  });
});

src/lifecycle/__tests__/unit/manifest-1-.source:
/**
 * @file Agent Plugins 1.1.0 support in `parseAgentPluginManifest()` / `parseAgentPluginMcpConfig()`.
 *
 * 1.1.0 changes only the `$schema` identifiers (spec text and both schemas otherwise match 1.0.0),
 * so these tests pin version selection: a real 1.1.0 package parses and installs, 1.1.0 grammar
 * violations are still refused, 1.0.0 keeps working, a plugin.json/mcp.json version mismatch
 * disables MCP (§10), an unknown 1.x is read with the newest known grammar plus one warning, and
 * a different major is refused.
 *
 * The fixture is Open Marketing's `content/agent-plugins/higgsfield-media` plugin.json + mcp.json,
 * copied verbatim at Open Marketing commit 13bbfa9.
 */
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "../legacy-test.js";
import { forceRemove } from "../fixtures/force-remove.js";
import { installAgentPlugin, resolveAgentPluginLayout } from "../test-support.js";
import type { AgentPluginArchiveEntry } from "../../install.js";
import { parseAgentPluginManifest, parseAgentPluginMcpConfig } from "../../manifest.js";

const FIXTURE = path.join(path.dirname(fileURLToPath(import.meta.url)), "../fixtures/open-marketing-higgsfield-media-1.1.0");
const OM_PLUGIN_TEXT = readFileSync(path.join(FIXTURE, "plugin.json"), "utf8");
const OM_PLUGIN = JSON.parse(OM_PLUGIN_TEXT) as Record<string, unknown>;
const OM_MCP = JSON.parse(readFileSync(path.join(FIXTURE, "mcp.json"), "utf8")) as Record<string, unknown>;
const OM_NAMESPACE = "io.github.ainsep.openmarketing";

const PLUGIN_1_0_0 = "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json";
const PLUGIN_1_1_0 = "https://agent-plugins.org/schemas/1.1.0/plugin.schema.json";
const MCP_1_0_0 = "https://agent-plugins.org/schemas/1.0.0/mcp.schema.json";
const MCP_1_1_0 = "https://agent-plugins.org/schemas/1.1.0/mcp.schema.json";

function parseMcp(value: unknown, pluginManifest?: unknown) {
  return parseAgentPluginMcpConfig({ value, extensionNamespace: OM_NAMESPACE }, { pluginManifest });
}

test("a real 1.1.0 plugin.json (Open Marketing higgsfield-media) parses with its extension namespace intact", () => {
  assert.equal(OM_PLUGIN.$schema, PLUGIN_1_1_0);
  const result = parseAgentPluginManifest({ value: OM_PLUGIN });
  assert.equal(result.ok, true, result.ok ? "" : result.errors.join("; "));
  if (!result.ok) return;
  assert.equal(result.manifest.name, "higgsfield-media");
  assert.equal(result.manifest.version, "0.1.0");
  assert.deepEqual(Object.keys(result.manifest.extensions ?? {}), [OM_NAMESPACE]);
  assert.deepEqual(result.warnings.filter((warning) => warning.startsWith("unrecognized")), []);
});

test("a real 1.1.0 mcp.json parses its closed streamable-http server alongside its 1.1.0 plugin.json", () => {
  assert.equal(OM_MCP.$schema, MCP_1_1_0);
  const result = parseMcp(OM_MCP, OM_PLUGIN);
  assert.equal(result.ok, true, result.ok ? "" : result.errors.join("; "));
  if (!result.ok) return;
  assert.deepEqual(result.config.serverIds, ["higgsfield"]);
  assert.deepEqual(result.config.servers.higgsfield, { type: "streamable-http", url: "https://mcp.higgsfield.ai/mcp" });
});

test("a 1.1.0 stdio server keeps its ${PLUGIN_ROOT} placeholders verbatim for the launcher to expand", () => {
  const result = parseMcp({
    $schema: MCP_1_1_0,
    mcpServers: { local: { type: "stdio", command: "node", args: ["${PLUGIN_ROOT}/bin/server.mjs"], cwd: "${PLUGIN_ROOT}" } },
  }, { $schema: PLUGIN_1_1_0, name: "local-tools" });
  assert.equal(result.ok, true);
  if (result.ok) assert.deepEqual(result.config.servers.local, { type: "stdio", command: "node", args: ["${PLUGIN_ROOT}/bin/server.mjs"], cwd: "${PLUGIN_ROOT}" });
});

test("installAgentPlugin publishes a 1.1.0 package (the installer no longer pins 1.0.0)", async () => {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-1-1-0-test-"));
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-1.1.0"));
    const entries = [["plugin.json", OM_PLUGIN_TEXT], ["skills/higgsfield/SKILL.md", "# Higgsfield\n"]].map(([entryPath, text]) => {
      const bytes = Buffer.from(text!, "utf8");
      return { kind: "file", entryPath, declaredSize: bytes.byteLength, executable: false, async *openReadStream() { yield bytes; } } as AgentPluginArchiveEntry;
    });
    const installed = await installAgentPlugin({
      archive,
      expectedSha256: createHash("sha256").update(archive).digest("hex"),
      archiveReader: { async *entries() { yield* entries; } },
      layout: resolveAgentPluginLayout({ cwd, env: {} }),
      workspaceId: "11111111-1111-4111-8111-111111111111",
    });
    assert.equal(installed.pluginId, "higgsfield-media");
    assert.equal(installed.license, "Apache-2.0");
  } finally {
    await forceRemove(cwd);
  }
});

test("1.1.0 grammar violations are still refused with the field named", () => {
  const badName = parseAgentPluginManifest({ value: { ...OM_PLUGIN, name: "Higgsfield Media" } });
  assert.equal(badName.ok, false);
  if (!badName.ok) assert.match(badName.errors.join("\n"), /'name' \('Higgsfield Media'\) must be 1-64 lowercase/);

  const noName = parseAgentPluginManifest({ value: { $schema: PLUGIN_1_1_0 } });
  assert.equal(noName.ok, false);
  if (!noName.ok) assert.deepEqual(noName.errors, ["plugin.json 'name' is required and must be a string"]);

  const noServers = parseMcp({ $schema: MCP_1_1_0 }, OM_PLUGIN);
  assert.equal(noServers.ok, false);
  if (!noServers.ok) assert.deepEqual(noServers.errors, ["mcp.json 'mcpServers' is required and must be an object"]);
});

test("a malformed 1.1.0 server entry is excluded without failing the file (§7.2.2 fail-open)", () => {
  const result = parseMcp({
    $schema: MCP_1_1_0,
    mcpServers: {
      reserved: { type: "stdio", command: "node", env: { PLUGIN_ROOT: "/elsewhere" } },
      unknown: { type: "websocket", url: "wss://example.com" },
      remote: { type: "sse", url: "https://example.com/sse" },
    },
  }, { $schema: PLUGIN_1_1_0, name: "mixed" });
  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.deepEqual(result.config.serverIds, ["reserved", "unknown", "remote"]);
  assert.deepEqual(Object.keys(result.config.servers), ["remote"]);
});

test("1.0.0 manifests and MCP configs parse exactly as before", () => {
  const manifest = parseAgentPluginManifest({ value: { $schema: PLUGIN_1_0_0, name: "ui-ux-design" } });
  assert.equal(manifest.ok, true);
  const mcp = parseMcp({ $schema: MCP_1_0_0, mcpServers: { main: { type: "stdio", command: "./server.js" } } }, { $schema: PLUGIN_1_0_0, name: "ui-ux-design" });
  assert.equal(mcp.ok, true);
  if (mcp.ok) assert.deepEqual(mcp.config.servers.main, { type: "stdio", command: "./server.js" });
});

test("mcp.json is refused when its version differs from plugin.json's, in either direction (§10)", () => {
  const older = parseMcp({ ...OM_MCP, $schema: MCP_1_0_0 }, OM_PLUGIN);
  assert.equal(older.ok, false);
  if (!older.ok) assert.deepEqual(older.errors, ["mcp.json targets Agent Plugins 1.0.0 but plugin.json targets 1.1.0; the versions must match"]);

  const newer = parseMcp(OM_MCP, { $schema: PLUGIN_1_0_0, name: "higgsfield-media" });
  assert.equal(newer.ok, false);
  if (!newer.ok) assert.deepEqual(newer.errors, ["mcp.json targets Agent Plugins 1.1.0 but plugin.json targets 1.0.0; the versions must match"]);
});

test("mcp.json alone (no plugin.json supplied) is checked only against the supported versions", () => {
  assert.equal(parseMcp(OM_MCP).ok, true);
});

for (const schema of [
  "https://agent-plugins.org/schemas/1.1/plugin.schema.json",
  "http://agent-plugins.org/schemas/1.1.0/plugin.schema.json",
  MCP_1_1_0,
  undefined,
]) {
  test(`plugin.json refuses the non-canonical $schema '${schema}' and lists the accepted identifiers`, () => {
    const result = parseAgentPluginManifest({ value: { ...OM_PLUGIN, $schema: schema } });
    assert.equal(result.ok, false);
    if (!result.ok) {
      assert.deepEqual(result.errors, [
        `plugin.json '$schema' must be '${PLUGIN_1_0_0}' or '${PLUGIN_1_1_0}' (Agent Plugins 1.0.0, 1.1.0, or another 1.x), got '${schema}'`,
      ]);
    }
  });
}

for (const version of ["1.2.0", "1.5.3"]) {
  test(`an unknown newer ${version} is read with the 1.1.0 grammar and exactly one warning naming the version`, () => {
    const pluginManifest = { ...OM_PLUGIN, $schema: `https://agent-plugins.org/schemas/${version}/plugin.schema.json` };
    const manifest = parseAgentPluginManifest({ value: pluginManifest });
    assert.equal(manifest.ok, true);
    if (manifest.ok) {
      assert.deepEqual(manifest.warnings.filter((warning) => warning.includes("Agent Plugins")), [
        `plugin.json targets Agent Plugins ${version}, newer than this loader knows; validated with the 1.1.0 grammar`,
      ]);
    }
    const mcp = parseMcp({ ...OM_MCP, $schema: `https://agent-plugins.org/schemas/${version}/mcp.schema.json` }, pluginManifest);
    assert.equal(mcp.ok, true);
    if (mcp.ok) assert.deepEqual(Object.keys(mcp.config.servers), ["higgsfield"]);
  });
}

test("an unknown 1.x still enforces the known grammar (bad name refused, unknown top-level field only warns)", () => {
  const schema = "https://agent-plugins.org/schemas/1.2.0/plugin.schema.json";
  const badName = parseAgentPluginManifest({ value: { $schema: schema, name: "Not Valid" } });
  assert.equal(badName.ok, false);
  const extra = parseAgentPluginManifest({ value: { $schema: schema, name: "ok", futureField: true } });
  assert.equal(extra.ok, true);
  if (extra.ok) assert.ok(extra.warnings.includes("unrecognized plugin.json field 'futureField' (ignored per spec)"));
});

test("a 1.2.0 mcp.json is refused beside a 1.1.0 plugin.json (versions must still match)", () => {
  const result = parseMcp({ ...OM_MCP, $schema: "https://agent-plugins.org/schemas/1.2.0/mcp.schema.json" }, OM_PLUGIN);
  assert.equal(result.ok, false);
  if (!result.ok) assert.deepEqual(result.errors, ["mcp.json targets Agent Plugins 1.2.0 but plugin.json targets 1.1.0; the versions must match"]);
});

for (const version of ["2.0.0", "0.9.0"]) {
  test(`a different major (${version}) is refused as an unsupported major version`, () => {
    const manifest = parseAgentPluginManifest({ value: { ...OM_PLUGIN, $schema: `https://agent-plugins.org/schemas/${version}/plugin.schema.json` } });
    assert.equal(manifest.ok, false);
    if (!manifest.ok) assert.deepEqual(manifest.errors, [`plugin.json targets Agent Plugins ${version}, an unsupported major version (supported: 1.x)`]);
    const mcp = parseMcp({ ...OM_MCP, $schema: `https://agent-plugins.org/schemas/${version}/mcp.schema.json` });
    assert.equal(mcp.ok, false);
    if (!mcp.ok) assert.deepEqual(mcp.errors, [`mcp.json targets Agent Plugins ${version}, an unsupported major version (supported: 1.x)`]);
  });
}

src/admin-surfaces/__tests__/action-tool.source:
/** Admin tools retain the screen's schema, capability, permission and revocation boundaries. */
import { describe, expect, test } from 'vitest';
import { buildAdminSurfaceActionTools } from '../action-tools.js';
import { createAdminSurfaceActionDispatcher } from '../action-dispatcher.js';
import { parseAdminSurfacesFile, type AdminSurfaceDescriptor } from '../descriptor.js';
import { createAdminSurfaceHandlerHost, type LoadedAdminSurfaceHandlers } from '../surface-handlers.js';
import { createAgentPluginToolProjection } from '../../lifecycle/tools/projection.js';
import { createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { fakeCapabilities } from '../../lifecycle/tools/__tests__/support.js';
import { createFakeSurfaceHost } from './surface-support.js';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';

const input = { type: 'object', properties: { value: { type: 'string' } }, required: ['value'] } as const;
const context = { workspaceId: 'workspace', principalId: 'owner', pluginId: 'acme', surfaceId: 'account' };
function descriptor(effect?: unknown): AdminSurfaceDescriptor {
  const parsed = parseAdminSurfacesFile({ raw: JSON.stringify({ schemaVersion: 1, surfaces: [{ id: 'account', title: 'Account', entry: 'index.html', handlerModule: 'handlers.mjs',
    actions: [{ name: 'save', input, result: { type: 'string' }, ...(effect === undefined ? {} : { effect }) }] }] }) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0]!;
}
function fixture() {
  const surface = descriptor();
  const fake = createFakeSurfaceHost();
  const issuedTokens = createIssuedTokenMemories();
  const host = createAdminSurfaceHandlerHost({ capabilities: fake.port, issuedTokens, hostKind: 'hosted' });
  const calls: unknown[] = [];
  const loaded: LoadedAdminSurfaceHandlers = { pluginId: 'acme', descriptor: { ...surface, handlerModule: 'handlers.mjs' }, module: { actions: {
    save: async ({ input: value, capabilities, context: scope }) => { calls.push({ value, scope }); await capabilities.state.set({ key: 'saved', value: 'yes' }); return 'saved'; },
  } } };
  host.sync({ loaded: [loaded], refusals: [] });
  let allowed = true;
  const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: surface }], handlersFor: host.handlersFor,
    authorize: async ({ context: who }) => { expect(who).toEqual(context); if (!allowed) throw new Error('denied'); },
  });
  const call = (value: unknown) => tools[0]!.tool.handler({ pluginId: 'acme', auth: context, input: value });
  return { surface, host, tools, calls, call, deny: () => { allowed = false; }, fake, issuedTokens };
}

describe('admin action tools', () => {
  test('declares the effect with write as the default and rejects unknown/null effects', () => {
    expect(descriptor().actions[0]!.effect).toBe('write');
    expect(descriptor('read').actions[0]!.effect).toBe('read');
    expect(descriptor('destructive').actions[0]!.effect).toBe('destructive');
    expect(() => descriptor('execute')).toThrow(/effect/);
    expect(() => descriptor(null)).toThrow(/effect/);
  });
  test('namespaces surface/action and calls exactly the screen handler with its capability scope', async () => {
    const f = fixture();
    expect(f.tools[0]!.tool.name).toBe('account_save');
    expect(f.tools[0]!.tool.effect).toBe('write');
    const screen = createAdminSurfaceActionDispatcher({ descriptor: f.surface, handlers: f.host.handlersFor(context) });
    const payload = { value: 'hello' };
    expect(await f.call({ payload })).toEqual(await screen.dispatch({ action: 'save', payload, context }));
    expect(f.calls).toHaveLength(2);
    expect(f.fake.log.calls).toEqual(['acme:state.set:{"key":"saved"}', 'acme:state.set:{"key":"saved"}']);
    expect(f.fake.state.get('workspace\u0000acme\u0000saved')).toBe('yes');
  });
  test('enforces permission before any handler/capability call', async () => {
    const f = fixture(); f.deny();
    await expect(f.call({ payload: { value: 'hello' } })).rejects.toThrow('denied');
    expect(f.calls).toEqual([]); expect(f.fake.log.calls).toEqual([]);
  });
  test.each([{}, { payload: {} }, { payload: { value: 1 } }, { payload: { value: 'x', extra: true } }, { payload: { value: 'x' }, extra: true }])('refuses invalid input %j before execution and disclosure', async (bad) => {
    const f = fixture();
    await expect(f.call(bad)).rejects.toThrow(/payload/);
    expect(() => f.tools[0]!.describeAffectedResources({ input: bad })).toThrow(/payload/);
    expect(f.calls).toEqual([]);
  });
  test('uses dispatcher result validation and returns a browser URL without opening anything', async () => {
    const f = fixture();
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], authorize: async () => {},
      handlersFor: () => ({ save: async () => ({ undeclared: true }) }),
    });
    expect(await tools[0]!.tool.handler({ pluginId: 'acme', auth: context, input: { payload: { value: 'hello' } } })).toMatchObject({ ok: false, error: { code: 'invalid-result' } });
    const links = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], authorize: async () => {}, handlersFor: () => ({ save: async () => 'https://auth.example.test/sign-in' }) });
    expect(await links[0]!.tool.handler({ pluginId: 'acme', auth: context, input: { payload: { value: 'hello' } } })).toEqual({ ok: true, result: 'https://auth.example.test/sign-in' });
  });
  test('shares projection withdrawal with executable tools; stale handlers cannot act', async () => {
    const f = fixture(); const registry = createPluginContributionRegistry({});
    const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, issuedTokens: f.issuedTokens,
      capabilities: () => fakeCapabilities({ tokenRequests: [], requests: [] }),
    });
    expect(projection.sync({ loaded: [], refusals: [], additionalTools: f.tools }).refusals).toEqual([]);
    const snapshot = registry.list({})[0]!;
    const held = snapshot.tools[0]!;
    expect(await projection.describeAffectedResources({ toolId: 'p_acme__account_save', input: { payload: { value: 'x' } } })).toEqual({ effect: 'write', resources: ['Account: save'] });
    projection.sync({ loaded: [], refusals: [] });
    expect(registry.list({})).toEqual([]);
    expect(await projection.describeAffectedResources({ toolId: 'p_acme__account_save', input: {} })).toBeNull();
    expect(() => held.handler({ pluginId: 'acme', sdk: snapshot.sdk, auth: { ...context, access: 'admin' }, input: { payload: { value: 'x' } } })).toThrow(/disabled/);
    expect(f.calls).toEqual([]);
  });
  test('refuses colliding ids across surface variants instead of selecting a handler', () => {
    const f = fixture(); const registry = createPluginContributionRegistry({});
    const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, issuedTokens: f.issuedTokens,
      capabilities: () => fakeCapabilities({ tokenRequests: [], requests: [] }),
    });
    const result = projection.sync({ loaded: [], refusals: [], additionalTools: [...f.tools, ...f.tools] });
    expect(result.refusals).toEqual(["agent tool 'p_acme__account_save' was not loaded: more than one contribution declares it"]);
    expect(registry.list({}).flatMap(row => row.tools)).toEqual([]);
  });
  test('a hand-built descriptor without an effect projects a write tool', () => {
    const { effect: _dropped, ...action } = descriptor().actions[0]!;
    const surface = { ...descriptor(), actions: [action] };
    const [tool] = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: surface }], handlersFor: () => ({}), authorize: async () => undefined });
    expect(tool!.tool.effect).toBe('write');
  });
  test('refuses an unauthenticated call before authorization or any handler runs', async () => {
    const f = fixture();
    const authorized: unknown[] = [];
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], handlersFor: f.host.handlersFor,
      authorize: async input => { authorized.push(input); } });
    await expect(tools[0]!.tool.handler({ pluginId: 'acme', auth: { workspaceId: 'workspace' }, input: { payload: { value: 'x' } } }))
      .rejects.toThrow('Admin actions require an authenticated principal.');
    expect(authorized).toEqual([]);
    expect(f.calls).toEqual([]);
  });
  test('the optional run decorator wraps the same dispatch and can decorate its outcome', async () => {
    const f = fixture();
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], handlersFor: f.host.handlersFor,
      authorize: async () => undefined }, { run: async ({ dispatch }) => ({ decorated: await dispatch() }) });
    const plain = await f.call({ payload: { value: 'hello' } });
    expect(await tools[0]!.tool.handler({ pluginId: 'acme', auth: context, input: { payload: { value: 'hello' } } })).toEqual({ decorated: plain });
    expect(f.calls).toHaveLength(2);
  });
  test('a live projected admin tool runs the same handler; an additional tool without an effect discloses as write', async () => {
    const f = fixture(); const registry = createPluginContributionRegistry({});
    const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, issuedTokens: f.issuedTokens,
      capabilities: () => fakeCapabilities({ tokenRequests: [], requests: [] }),
    });
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], handlersFor: f.host.handlersFor, authorize: async () => undefined });
    const { effect: _dropped, ...withoutEffect } = tools[0]!.tool;
    const failing = { pluginId: 'acme', tool: { ...withoutEffect, name: 'account_probe' }, describeAffectedResources: () => { throw new Error('resource lookup failed'); } };
    const plain = { ...failing, tool: { ...withoutEffect, name: 'account_plain' }, describeAffectedResources: () => ['Account: plain'] };
    expect(projection.sync({ loaded: [], refusals: [], additionalTools: [...tools, failing, plain] }).refusals).toEqual([]);
    const snapshot = registry.list({})[0]!;
    const live = snapshot.tools.find(tool => tool.name === 'account_save')!;
    expect(await live.handler({ pluginId: 'acme', sdk: snapshot.sdk, auth: { ...context, access: 'admin' }, input: { payload: { value: 'live' } } })).toEqual(await f.call({ payload: { value: 'live' } }));
    expect(f.calls).toHaveLength(2);
    expect(await projection.describeAffectedResources({ toolId: 'p_acme__account_plain', input: {} })).toEqual({ effect: 'write', resources: ['Account: plain'] });
    await expect(projection.describeAffectedResources({ toolId: 'p_acme__account_probe', input: {} })).rejects.toThrow('resource lookup failed');
  });
});

